INSERT INTO categories (id, name, description) VALUES ('defence-exam', 'Defence Exams (NDA/CDS/AFCAT)', 'General knowledge, current affairs, and defence/military awareness for NDA, CDS, and AFCAT entrance exams.');
INSERT INTO question_sets (id, owner_user_id, title, track, visibility, created_at, approved_at, approved_by) VALUES ('defence-exam-bank', NULL, 'Defence Exam Prep', 'defence', 'shared', '2026-11-14T06:17:56.365Z', '2026-11-14T06:17:56.365Z', NULL);
INSERT INTO question_set_categories (set_id, category_id) VALUES ('defence-exam-bank', 'defence-exam');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00001', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 0, 'Who composed India''s National Anthem, ''Jana Gana Mana''?', 'The National Anthem was composed by **Rabindranath Tagore**, originally written in Bengali.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00002', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 1, 'Who wrote India''s National Song, ''Vande Mataram''?', 'The National Song was composed by **Bankim Chandra Chattopadhyay** in Sanskrit-Bengali.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00003', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 2, 'What is depicted in India''s National Emblem and what is its motto?', 'The National Emblem is an adaptation of the **Lion Capital of Ashoka at Sarnath**, adopted on **26 January 1950**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00004', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 3, 'What are India''s National Animal, Bird, Flower, and Tree?', 'The National Animal is the **Royal Bengal Tiger**, the National Bird is the **Indian Peacock**, the National Flower is the **Lotus**, and the National Tree is the **Banyan Tree**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00005', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 4, 'Which aquatic animal has been declared India''s National Aquatic Animal?', 'The **Ganges River Dolphin (Platanista gangetica)** was declared the National Aquatic Animal in **2009** to highlight river ecosystem conservation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00006', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 5, 'Does India have an officially declared National Sport?', 'No. The Government of India has clarified in Parliament that **no sport has been officially declared the National Sport**, though hockey is popularly associated with that status due to India''s Olympic dominance in the sport.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00007', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 6, 'When is ''National Science Day'' observed in India and why?', 'National Science Day is observed on **28 February** every year to commemorate **Sir C.V. Raman''s discovery of the ''Raman Effect'' in 1928**, for which he won the **1930 Nobel Prize in Physics**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00008', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 7, 'Why is 5 September observed as Teachers'' Day in India?', 'It marks the birthday of **Dr. Sarvepalli Radhakrishnan**, India''s first Vice President and second President, who was also a renowned philosopher and teacher.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00009', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 8, 'Why is 12 January celebrated as National Youth Day?', 'It is the birth anniversary of **Swami Vivekananda** (born 1863), whose teachings on youth empowerment and spirituality inspired the observance, started in **1985**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00010', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 9, 'Who were the first recipients of the Bharat Ratna, India''s highest civilian award?', 'Instituted in **1954**, the first Bharat Ratna awardees were **C. Rajagopalachari, Dr. Sarvepalli Radhakrishnan, and Dr. C.V. Raman**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00011', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 10, 'What are the three categories of Padma Awards, in descending order of precedence?', 'The Padma Awards consist of the **Padma Vibhushan** (exceptional and distinguished service), **Padma Bhushan** (distinguished service of a high order), and **Padma Shri** (distinguished service).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00012', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 11, 'Who was the first Indian to win a Nobel Prize, and in which category?', '**Rabindranath Tagore** won the **Nobel Prize in Literature in 1913** for his collection of poems, ''Gitanjali'', becoming the first non-European laureate.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00013', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 12, 'Which Indian woman won the Nobel Peace Prize in 1979?', '**Mother Teresa**, founder of the Missionaries of Charity in Kolkata, won the **Nobel Peace Prize in 1979** for her work with the poor and destitute.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00014', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 13, 'Who is the only Indian to win a Nobel Prize in Economics?', '**Amartya Sen** won the **Nobel Memorial Prize in Economic Sciences in 1998** for his contributions to welfare economics and work on famine and poverty.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00015', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 14, 'What is the Jnanpith Award and who received it first?', 'The **Jnanpith Award** is India''s highest literary honour, given for an outstanding contribution to Indian literature.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00016', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 15, 'What is the Major Dhyan Chand Khel Ratna Award?', 'It is India''s **highest sporting honour**, renamed in **2021** after hockey legend **Major Dhyan Chand** (previously called the Rajiv Gandhi Khel Ratna).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00017', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 16, 'What is the Dronacharya Award given for?', 'The **Dronacharya Award** recognises **outstanding coaches** who have produced medal-winning performances at national and international levels.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00018', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 17, 'List the eight classical dance forms of India recognised by the Sangeet Natak Akademi.', 'The eight recognised classical dance forms are **Bharatanatyam** (Tamil Nadu), **Kathak** (North India), **Kathakali** and **Mohiniyattam** (Kerala), **Odissi** (Odisha), **Manipuri** (Manipur), **Kuchipudi** (Andhra Pradesh), and **Sattriya** (Assam).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00019', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 18, 'Which four monuments were among the first Indian sites inscribed as UNESCO World Heritage Sites in 1983?', 'The first Indian sites inscribed in **1983** were the **Agra Fort**, **Ajanta Caves**, **Ellora Caves**, and the **Taj Mahal**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00020', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 19, 'Who became the first Indian to win an individual Olympic gold medal?', '**Abhinav Bindra** won gold in the **10m Air Rifle event at the 2008 Beijing Olympics**, becoming the first Indian to win an individual Olympic gold medal.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00021', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 20, 'Who was the first Indian woman to win an Olympic medal?', '**Karnam Malleswari** won a **bronze medal in weightlifting at the 2000 Sydney Olympics**, becoming the first Indian woman to win an Olympic medal.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00022', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 21, 'Which Indian athlete won gold in javelin throw at the 2020 Tokyo Olympics?', '**Neeraj Chopra** won India''s first-ever Olympic gold medal in **athletics**, throwing the javelin **87.58 metres** at the Tokyo 2020 Games (held in 2021).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00023', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 22, 'Who is India''s first world chess champion, and who is the youngest-ever world chess champion?', '**Viswanathan Anand** became India''s first World Chess Champion, winning the title five times between 2000 and 2012.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00024', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 23, 'In which years has India won the Cricket World Cup?', 'India has won the **ODI Cricket World Cup in 1983 and 2011**, and the **T20 World Cup in 2007 and 2024**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00025', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 24, 'Who was the first Indian to travel to space?', '**Rakesh Sharma** flew aboard **Soyuz T-11** in **April 1984** as part of a joint Indo-Soviet mission, becoming the first Indian in space.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00026', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 25, 'Who was the first Indian-origin woman in space?', '**Kalpana Chawla**, an Indian-born American astronaut, flew on the Space Shuttle **Columbia** in 1997 and tragically died in the Columbia disaster in 2003.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00027', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 26, 'What was significant about India''s Mangalyaan (Mars Orbiter Mission)?', 'Launched in **2013**, Mangalyaan made India the **first country to reach Mars orbit in its maiden attempt**, and ISRO became the fourth space agency to reach Mars.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00028', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 27, 'What made Chandrayaan-3''s landing in 2023 historic?', 'Chandrayaan-3 made a successful soft landing near the **lunar south pole on 23 August 2023**, making India the **first country to land near the Moon''s south pole** and the fourth to achieve a soft lunar landing.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00029', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 28, 'When is National Space Day observed and why?', '**23 August** is observed as **National Space Day**, commemorating the date of Chandrayaan-3''s successful Moon landing in 2023.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00030', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 29, 'Which is the tallest statue in the world and where is it located?', 'The **Statue of Unity**, depicting **Sardar Vallabhbhai Patel**, stands **182 metres** tall in **Gujarat** near the Narmada dam, and was inaugurated in **2018**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00031', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 30, 'When is International Day of Yoga observed, and what is its origin?', '**21 June** is observed as **International Day of Yoga**, following a proposal by **Prime Minister Narendra Modi** at the **UN General Assembly in 2014**; the first observance was in 2015.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00032', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 31, 'Which is the oldest stock exchange in Asia?', 'The **Bombay Stock Exchange (BSE)**, established in **1875**, is the oldest stock exchange in Asia.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00033', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 32, 'Who designed the Indian Rupee symbol (₹) and when was it adopted?', 'The Rupee symbol was designed by **D. Udaya Kumar** and officially adopted by the Government of India in **2010**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00034', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 33, 'When was the Reserve Bank of India established?', 'The RBI was established on **1 April 1935** under the **RBI Act, 1934**, and was nationalised in **1949**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00035', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 34, 'Which Indian author won the Booker Prize for ''The God of Small Things''?', '**Arundhati Roy** won the **Booker Prize in 1997** for her debut novel, ''The God of Small Things''.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00036', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 35, 'Who became the first Indian woman to win the International Booker Prize?', '**Geetanjali Shree** won the **International Booker Prize in 2022** for ''Tomb of Sand'' (Hindi: ''Ret Samadhi''), translated by **Daisy Rockwell**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00037', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 36, 'Who wrote the epic Mahabharata?', 'The Mahabharata is traditionally attributed to the sage **Ved Vyasa (Krishna Dwaipayana Vyasa)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00038', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 37, 'Who is credited with composing the Ramayana?', 'The Ramayana is attributed to the sage **Valmiki** and is considered the **''Adi Kavya'' (first epic poem)** in Sanskrit literature.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00039', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 38, 'Which Sanskrit poet-dramatist wrote ''Abhijnanasakuntalam''?', '**Kalidasa**, regarded as the greatest classical Sanskrit poet and playwright, wrote ''Abhijnanasakuntalam'' along with works like ''Meghaduta'' and ''Raghuvamsa''.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00040', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 39, 'When is World Environment Day observed?', '**World Environment Day** is observed on **5 June** each year, marking the anniversary of the opening of the **1972 UN Conference on the Human Environment in Stockholm**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00041', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 40, 'What is the Swachh Bharat Mission and when was it launched?', 'Launched on **2 October 2014** (Gandhi''s birth anniversary), the **Swachh Bharat Mission** aims at achieving universal sanitation coverage and eliminating open defecation across India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00042', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 41, 'What is the objective of the Pradhan Mantri Jan Dhan Yojana?', 'Launched in **2014**, it aims at **financial inclusion** by providing every household access to banking, savings, credit, insurance, and pension facilities.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00043', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 42, 'Where are the headquarters of the United Nations and WHO located?', 'The **United Nations** is headquartered in **New York, USA**, while the **World Health Organization (WHO)** is headquartered in **Geneva, Switzerland**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00044', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 43, 'Where is UNESCO headquartered?', '**UNESCO (United Nations Educational, Scientific and Cultural Organization)** is headquartered in **Paris, France**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00045', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 44, 'When did India hold the G20 Presidency, and what was its theme?', 'India held the **G20 Presidency from December 2022 to November 2023**, hosting the New Delhi Summit in September 2023 under the theme **''Vasudhaiva Kutumbakam'' (''One Earth, One Family, One Future'')**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00046', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 45, 'Who received the Nobel Peace Prize in 2014 for work against child labour, alongside Malala Yousafzai?', '**Kailash Satyarthi**, an Indian child rights activist, shared the **2014 Nobel Peace Prize** with Malala Yousafzai for their struggle against the suppression of children and for children''s right to education.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00047', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 46, 'Who was the first woman Speaker of the Lok Sabha?', '**Meira Kumar** became the first woman Speaker of the Lok Sabha, serving from **2009 to 2014**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00048', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 47, 'Who was India''s first woman Prime Minister?', '**Indira Gandhi** became India''s first woman Prime Minister in **1966** and remains the only woman to hold the office.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00049', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 48, 'Who was India''s first woman President?', '**Pratibha Patil** served as India''s first woman President from **2007 to 2012**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00050', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 49, 'Who was independent India''s first Indian-origin woman IPS officer?', '**Kiran Bedi** became India''s **first woman IPS officer**, joining the Indian Police Service in **1972**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00051', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 50, 'What important distinction does the National Calendar (Saka Calendar) hold in India?', 'The **Saka calendar**, adopted alongside the Gregorian calendar in **1957**, is India''s official national calendar, beginning with the month of **Chaitra** and based on the Saka Era starting 78 CE.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00052', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 51, 'Who composed India''s National Pledge?', 'The National Pledge was written by **Pydimarri Venkata Subba Rao** in Telugu in 1962, and translated into other Indian languages; it is recited daily in schools.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00053', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 52, 'Who won India''s first individual Olympic medal in badminton?', '**Saina Nehwal** won a **bronze medal in badminton at the 2012 London Olympics**, becoming the first Indian badminton player to win an Olympic medal.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00054', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 53, 'Which Indian woman became the first to win two individual Olympic medals?', '**P.V. Sindhu** won a **silver medal at Rio 2016** and a **bronze medal at Tokyo 2020**, making her the first Indian woman to win two individual Olympic medals.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00055', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 54, 'What is the significance of the lotus flower as India''s National Flower?', 'The **lotus (Nelumbo nucifera)** symbolises **purity, prosperity, and spiritual enlightenment** in Indian culture, and is deeply rooted in Hindu and Buddhist iconography.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00056', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 55, 'Which Indian city is known as the ''Silicon Valley of India''?', '**Bengaluru (Bangalore)**, Karnataka, is known as the ''Silicon Valley of India'' due to its concentration of IT companies and startups.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00057', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 56, 'What is the ''Ashoka Chakra'' and where does it appear on the National Flag?', 'The **Ashoka Chakra** is a 24-spoked wheel representing the eternal wheel of law (Dharma Chakra), placed at the **centre of the white band** of the National Flag, adopted on **22 July 1947**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00058', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 57, 'What are the proportions and colours of the Indian National Flag (Tiranga)?', 'The flag has a **3:2 width-to-length ratio**, with three horizontal bands of **saffron (courage), white (peace, with the Ashoka Chakra), and green (prosperity)**, designed originally by **Pingali Venkayya**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00059', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 58, 'Who designed the Indian National Flag?', 'The basic design of the Indian National Flag was conceived by **Pingali Venkayya**, and it was adopted in its current form by the Constituent Assembly on **22 July 1947**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00060', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 59, 'What is the significance of 21 October in the context of Indian Police history?', '**21 October** is observed as **Police Commemoration Day**, marking the anniversary of the 1959 Hot Springs clash in Ladakh where ten CRPF personnel were martyred.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00061', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 60, 'Which Indian scientist is associated with the discovery of the ''Bose-Einstein Statistics''?', '**Satyendra Nath Bose** collaborated with Albert Einstein on quantum statistics, giving rise to the term **''Boson''** (a class of subatomic particles) in his honour.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00062', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 61, 'Who is regarded as the ''Father of the Indian Space Programme''?', '**Dr. Vikram Sarabhai** is regarded as the father of the Indian space programme, and he founded the **Physical Research Laboratory** and was instrumental in establishing ISRO in **1969**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00063', 'defence-exam-bank', 'General Knowledge & Static GK', 0, 62, 'Who is known as the ''Missile Man of India''?', '**Dr. A.P.J. Abdul Kalam**, who later became India''s 11th President (2002-2007), is known as the ''Missile Man of India'' for his pivotal role in missile and space programmes.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00064', 'defence-exam-bank', 'History & Culture', 1, 0, 'Which river valley civilisation is considered the earliest urban civilisation of the Indian subcontinent?', 'The **Indus Valley Civilisation (Harappan Civilisation)**, dating to around **2500-1900 BCE**, is the earliest known urban civilisation in the subcontinent, centred on sites like **Harappa and Mohenjo-daro**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00065', 'defence-exam-bank', 'History & Culture', 1, 1, 'Which Harappan site is famous for its ''Great Bath''?', '**Mohenjo-daro**, located in present-day Sindh, Pakistan, is famous for its **Great Bath**, a large public water tank believed to have been used for ritual bathing.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00066', 'defence-exam-bank', 'History & Culture', 1, 2, 'Which Harappan site had a well-planned dockyard, suggesting maritime trade?', '**Lothal**, in present-day Gujarat, had an artificial **dockyard**, indicating that the Harappans engaged in maritime trade with regions like Mesopotamia.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00067', 'defence-exam-bank', 'History & Culture', 1, 3, 'What was the primary script used by the Indus Valley Civilisation, and has it been deciphered?', 'The Harappans used the **Indus script**, a pictographic script found on seals, which remains **undeciphered** to date despite many attempts.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00068', 'defence-exam-bank', 'History & Culture', 1, 4, 'Who composed the Rigveda and what is its structure?', 'The **Rigveda**, the oldest of the four Vedas (composed c. 1500-1000 BCE), is a collection of **1,028 hymns (suktas)** organised into **ten books (mandalas)**, dedicated chiefly to deities like Agni and Indra.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00069', 'defence-exam-bank', 'History & Culture', 1, 5, 'Who founded Buddhism, and where did he attain enlightenment?', '**Siddhartha Gautama (the Buddha)** founded Buddhism in the 6th century BCE, attaining enlightenment under the **Bodhi tree at Bodh Gaya**, Bihar.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00070', 'defence-exam-bank', 'History & Culture', 1, 6, 'Where did Buddha deliver his first sermon?', 'Buddha delivered his first sermon, known as the **''Dhammachakra Pravartana''**, at **Sarnath**, near Varanasi.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00071', 'defence-exam-bank', 'History & Culture', 1, 7, 'Who founded Jainism as it is practised today, and who were his predecessors called?', '**Mahavira (Vardhamana)**, the 24th Tirthankara, is regarded as the chief propagator of Jainism in the 6th century BCE; the Tirthankaras before him are considered earlier spiritual teachers in the Jain tradition.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00072', 'defence-exam-bank', 'History & Culture', 1, 8, 'Who founded the Mauryan Empire and when?', '**Chandragupta Maurya** founded the Mauryan Empire around **321 BCE**, with guidance from his mentor **Chanakya (Kautilya)**, author of the ''Arthashastra''.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00073', 'defence-exam-bank', 'History & Culture', 1, 9, 'Which Mauryan emperor embraced Buddhism after the Kalinga War?', '**Emperor Ashoka** embraced Buddhism after witnessing the bloodshed of the **Kalinga War (261 BCE)**, subsequently promoting the policy of ''Dhamma'' through edicts inscribed on pillars and rocks.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00074', 'defence-exam-bank', 'History & Culture', 1, 10, 'What are the Ashokan Edicts and in which scripts were they mainly written?', 'Ashokan Edicts are inscriptions on **rocks and pillars** conveying moral and administrative messages; they were mainly written in the **Brahmi script**, with some in Kharosthi, Greek, and Aramaic in the northwest.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00075', 'defence-exam-bank', 'History & Culture', 1, 11, 'Who founded the Gupta Empire, often called the ''Golden Age'' of ancient India?', '**Sri Gupta** founded the dynasty, but it was **Chandragupta I** who established the empire''s prominence; the Gupta period (4th-6th century CE) is called the ''Golden Age'' for its achievements in science, art, and literature.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00076', 'defence-exam-bank', 'History & Culture', 1, 12, 'Which Gupta ruler is often identified with the title ''Vikramaditya'' and associated with the ''Navratnas'' (nine gems)?', '**Chandragupta II (Vikramaditya)** is associated with a court of nine luminaries including the poet **Kalidasa**, during the peak of the Gupta Empire.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00077', 'defence-exam-bank', 'History & Culture', 1, 13, 'Which Indian mathematician-astronomer of the Gupta era is credited with early use of zero and calculating the value of pi?', '**Aryabhata**, author of the ''Aryabhatiya'' (499 CE), made key contributions including an approximation of **pi** and placing the Earth''s rotation on its axis as the cause of day and night.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00078', 'defence-exam-bank', 'History & Culture', 1, 14, 'Who was the Chinese traveller who visited India during Harshavardhana''s reign?', '**Hiuen Tsang (Xuanzang)** visited India in the 7th century CE during the reign of **Harshavardhana** and left detailed accounts of contemporary society and Nalanda University.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00079', 'defence-exam-bank', 'History & Culture', 1, 15, 'Which ancient Indian seat of learning was a renowned Buddhist centre visited by foreign scholars?', '**Nalanda University**, in present-day Bihar, was a major centre of Buddhist learning that attracted scholars from across Asia between the 5th and 12th centuries CE.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00080', 'defence-exam-bank', 'History & Culture', 1, 16, 'Who founded the Delhi Sultanate and which dynasty did he start?', '**Qutb-ud-din Aibak**, a former slave-general of Muhammad Ghori, founded the **Slave (Mamluk) Dynasty** in **1206 CE**, marking the start of the Delhi Sultanate.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00081', 'defence-exam-bank', 'History & Culture', 1, 17, 'Which monument did Qutb-ud-din Aibak begin constructing in Delhi?', 'He began construction of the **Qutub Minar**, which was later completed by his successor **Iltutmish**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00082', 'defence-exam-bank', 'History & Culture', 1, 18, 'Who was the only woman ruler of the Delhi Sultanate?', '**Razia Sultana**, daughter of Iltutmish, ruled Delhi from **1236 to 1240 CE**, the only woman to sit on the throne of Delhi during the Sultanate period.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00083', 'defence-exam-bank', 'History & Culture', 1, 19, 'Which ruler of the Khilji dynasty introduced market control reforms?', '**Alauddin Khilji** introduced extensive **market control reforms** fixing prices of commodities to maintain a large standing army at low cost.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00084', 'defence-exam-bank', 'History & Culture', 1, 20, 'Which ruler attempted to shift the capital from Delhi to Daulatabad?', '**Muhammad bin Tughlaq** shifted the capital from Delhi to **Daulatabad (Devagiri)** in the 14th century, a decision later reversed due to practical difficulties.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00085', 'defence-exam-bank', 'History & Culture', 1, 21, 'Who founded the Vijayanagara Empire in South India?', '**Harihara and Bukka**, brothers who founded the empire in **1336 CE**, established Vijayanagara as a bulwark against the Deccan Sultanates.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00086', 'defence-exam-bank', 'History & Culture', 1, 22, 'Who was the most famous ruler of the Vijayanagara Empire, known for his patronage of the arts and the Hampi capital?', '**Krishnadevaraya** (reign 1509-1529 CE) is regarded as the greatest ruler of the Vijayanagara Empire, a great patron of Telugu and Sanskrit literature.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00087', 'defence-exam-bank', 'History & Culture', 1, 23, 'Who founded the Bhakti-era Sikh faith?', '**Guru Nanak Dev**, born in 1469 CE at Talwandi (Nankana Sahib), founded Sikhism, emphasising devotion to one formless God.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00088', 'defence-exam-bank', 'History & Culture', 1, 24, 'Who was the founder of the Mughal Empire and in which battle did he establish it?', '**Babur** founded the Mughal Empire after defeating **Ibrahim Lodi** at the **First Battle of Panipat in 1526 CE**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00089', 'defence-exam-bank', 'History & Culture', 1, 25, 'Which Mughal emperor built the Taj Mahal, and in whose memory?', '**Shah Jahan** built the **Taj Mahal** in Agra in memory of his wife **Mumtaz Mahal**, construction spanning roughly 1632-1653 CE.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00090', 'defence-exam-bank', 'History & Culture', 1, 26, 'Which Mughal emperor is credited with the policy of religious tolerance and the ''Din-i-Ilahi''?', '**Akbar** pursued a policy of religious tolerance, abolished the ''jizya'' tax on non-Muslims, and introduced the syncretic faith **''Din-i-Ilahi''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00091', 'defence-exam-bank', 'History & Culture', 1, 27, 'Who founded the Maratha Empire and was crowned Chhatrapati in 1674?', '**Shivaji Maharaj** founded the Maratha Empire and was crowned **Chhatrapati at Raigad in 1674**, known for his guerrilla warfare tactics and administrative system.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00092', 'defence-exam-bank', 'History & Culture', 1, 28, 'What was the ''Ashtapradhan'' in the Maratha administrative system?', 'The **''Ashtapradhan''** was Shivaji''s council of **eight ministers**, each responsible for a specific administrative function, such as the Peshwa (Prime Minister) and Sar-i-Naubat (military chief).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00093', 'defence-exam-bank', 'History & Culture', 1, 29, 'Who was the founder of the Sikh Khalsa Panth?', '**Guru Gobind Singh**, the tenth Sikh Guru, founded the **Khalsa Panth in 1699**, establishing a distinct identity and code of conduct for Sikhs.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00094', 'defence-exam-bank', 'History & Culture', 1, 30, 'What was the main reason for the English East India Company''s victory at the Battle of Plassey (1757)?', 'The Company''s victory over **Siraj-ud-Daulah**, Nawab of Bengal, was aided by the **betrayal of Mir Jafar**, the Nawab''s commander, which gave the British effective control over Bengal.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00095', 'defence-exam-bank', 'History & Culture', 1, 31, 'Which battle in 1764 consolidated British control over Bengal, Bihar, and Odisha?', 'The **Battle of Buxar (1764)**, where the British defeated the combined forces of Mir Qasim, Shuja-ud-Daulah, and Shah Alam II, led to the **Treaty of Allahabad (1765)** and the grant of ''Diwani'' rights to the Company.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00096', 'defence-exam-bank', 'History & Culture', 1, 32, 'Who was the first Governor-General of Bengal under British rule?', '**Warren Hastings** became the first Governor-General of Bengal in **1773**, under the Regulating Act.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00097', 'defence-exam-bank', 'History & Culture', 1, 33, 'What triggered the Revolt of 1857?', 'The immediate trigger was the introduction of the **Enfield rifle cartridges**, rumoured to be greased with cow and pig fat, offending both Hindu and Muslim sepoys; it began at **Meerut on 10 May 1857**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00098', 'defence-exam-bank', 'History & Culture', 1, 34, 'Who was proclaimed the symbolic leader of the Revolt of 1857 at Delhi?', '**Bahadur Shah Zafar II**, the last Mughal emperor, was proclaimed the symbolic leader by the rebelling sepoys, though real power lay with regional leaders.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00099', 'defence-exam-bank', 'History & Culture', 1, 35, 'Who led the 1857 revolt in Jhansi?', '**Rani Lakshmibai of Jhansi** led the resistance in her region and died fighting British forces in 1858, becoming an iconic figure of the uprising.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00100', 'defence-exam-bank', 'History & Culture', 1, 36, 'What was the immediate constitutional consequence of the Revolt of 1857?', 'The **Government of India Act, 1858** transferred power from the East India Company directly to the **British Crown**, ending Company rule.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00101', 'defence-exam-bank', 'History & Culture', 1, 37, 'Who founded the Indian National Congress and in which year?', 'The Indian National Congress was founded in **1885** with **A.O. Hume**, a retired British civil servant, playing a key organising role; its first session was presided over by **W.C. Bonnerjee** in Bombay.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00102', 'defence-exam-bank', 'History & Culture', 1, 38, 'Who was the Viceroy responsible for the Partition of Bengal in 1905?', '**Lord Curzon** effected the **Partition of Bengal in 1905**, ostensibly for administrative convenience but widely seen as a ''divide and rule'' tactic; it was annulled in **1911**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00103', 'defence-exam-bank', 'History & Culture', 1, 39, 'What was the Swadeshi Movement a response to?', 'The **Swadeshi Movement (1905-08)** emerged in response to the Partition of Bengal, promoting the boycott of British goods and the use of indigenous products.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00104', 'defence-exam-bank', 'History & Culture', 1, 40, 'Who founded the Muslim League in 1906?', 'The **All-India Muslim League** was founded in **1906** at Dacca, with early leadership that included the **Aga Khan III**, to safeguard the political rights of Muslims.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00105', 'defence-exam-bank', 'History & Culture', 1, 41, 'What was the significance of the Lucknow Pact of 1916?', 'The **Lucknow Pact (1916)** marked a temporary **unity between the Indian National Congress and the Muslim League**, agreeing on a scheme of constitutional reforms.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00106', 'defence-exam-bank', 'History & Culture', 1, 42, 'Which massacre occurred at Jallianwala Bagh, Amritsar, in 1919?', 'On **13 April 1919**, General **Reginald Dyer** ordered troops to fire on an unarmed crowd gathered at **Jallianwala Bagh**, killing hundreds, a turning point that galvanised the freedom movement.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00107', 'defence-exam-bank', 'History & Culture', 1, 43, 'Why did Mahatma Gandhi call off the Non-Cooperation Movement in 1922?', 'Gandhi suspended the **Non-Cooperation Movement** after the **Chauri Chaura incident (February 1922)**, in which a violent mob killed policemen, which he felt violated the movement''s principle of non-violence.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00108', 'defence-exam-bank', 'History & Culture', 1, 44, 'What was the purpose of Gandhi''s Dandi March (Salt Satyagraha) in 1930?', 'The **Dandi March** (12 March-6 April 1930) was a 24-day march from Sabarmati Ashram to **Dandi, Gujarat**, to break the British salt monopoly by producing salt from seawater, launching the **Civil Disobedience Movement**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00109', 'defence-exam-bank', 'History & Culture', 1, 45, 'When was the Quit India Movement launched and with what call?', 'Launched on **8 August 1942** at the Bombay session of the AICC, the movement carried Gandhi''s call to **''Do or Die''**, demanding immediate British withdrawal from India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00110', 'defence-exam-bank', 'History & Culture', 1, 46, 'Who founded the Indian National Army (Azad Hind Fauj) with Japanese support during WWII?', '**Subhas Chandra Bose** reorganised and led the **Indian National Army (INA)**, also serving as head of the **Azad Hind Government**, formed in 1943.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00111', 'defence-exam-bank', 'History & Culture', 1, 47, 'What was the Cabinet Mission Plan of 1946?', 'The **Cabinet Mission (1946)**, sent by Britain, proposed a federal structure for a united India with grouped provinces, but its failure to satisfy both Congress and the Muslim League contributed to the eventual Partition.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00112', 'defence-exam-bank', 'History & Culture', 1, 48, 'Who was the last Viceroy of India who oversaw the transfer of power in 1947?', '**Lord Mountbatten** served as the last Viceroy of British India, overseeing independence and partition on **15 August 1947**, under the **Indian Independence Act, 1947**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00113', 'defence-exam-bank', 'History & Culture', 1, 49, 'Who drafted the plan for the partition of India, known as the ''Mountbatten Plan''?', 'The **Mountbatten Plan (June 1947)** laid out the basis for partitioning British India into **India and Pakistan**, accepted by both the Congress and the Muslim League.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00114', 'defence-exam-bank', 'History & Culture', 1, 50, 'Who chaired the Boundary Commission that demarcated the India-Pakistan border in 1947?', '**Sir Cyril Radcliffe** chaired the Boundary Commission, and the border he demarcated came to be known as the **Radcliffe Line**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00115', 'defence-exam-bank', 'History & Culture', 1, 51, 'Who is regarded as the architect of India''s political integration of princely states?', '**Sardar Vallabhbhai Patel**, India''s first Deputy Prime Minister and Home Minister, is credited with the **integration of over 560 princely states** into the Indian Union, earning the title ''Iron Man of India''.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00116', 'defence-exam-bank', 'History & Culture', 1, 52, 'Who assassinated Mahatma Gandhi, and when?', '**Nathuram Godse** assassinated Mahatma Gandhi on **30 January 1948** in New Delhi; this date is observed as **Martyrs'' Day**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00117', 'defence-exam-bank', 'History & Culture', 1, 53, 'Who chaired the Drafting Committee of the Indian Constitution?', '**Dr. B.R. Ambedkar** chaired the Drafting Committee of the Constituent Assembly, earning him the title ''Father of the Indian Constitution''.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00118', 'defence-exam-bank', 'History & Culture', 1, 54, 'Who founded the Arya Samaj and what was its chief aim?', '**Swami Dayananda Saraswati** founded the **Arya Samaj in 1875**, aiming to reform Hindu society by returning to Vedic principles and opposing idol worship and caste rigidity.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00119', 'defence-exam-bank', 'History & Culture', 1, 55, 'Who founded the Brahmo Samaj and campaigned against the practice of Sati?', '**Raja Ram Mohan Roy** founded the **Brahmo Samaj in 1828** and was instrumental in the abolition of **Sati** through the Bengal Sati Regulation of 1829.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00120', 'defence-exam-bank', 'History & Culture', 1, 56, 'Who founded the Ramakrishna Mission?', '**Swami Vivekananda** founded the **Ramakrishna Mission in 1897**, in honour of his guru Ramakrishna Paramahamsa, emphasising service to humanity (''daridra narayana seva'').', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00121', 'defence-exam-bank', 'History & Culture', 1, 57, 'Which Bhakti saint-poet is associated with devotional compositions to Lord Krishna and the ''Sur Sagar''?', '**Surdas**, a blind poet of the 16th century, composed devotional verses on Krishna in works like the **''Sur Sagar''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00122', 'defence-exam-bank', 'History & Culture', 1, 58, 'Which medieval saint-poet, a weaver by profession, preached the unity of Hindus and Muslims?', '**Kabir**, a 15th-century mystic poet, preached against religious orthodoxy of both Hinduism and Islam, composing couplets (''dohas'') still widely quoted.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00123', 'defence-exam-bank', 'History & Culture', 1, 59, 'Which architectural style blends Hindu and Islamic elements, prominent during the Delhi Sultanate and Mughal periods?', 'The **Indo-Islamic architectural style** blends features like domes, arches, and minarets with indigenous Indian decorative elements, seen in structures such as the **Qutub Minar and Humayun''s Tomb**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00124', 'defence-exam-bank', 'History & Culture', 1, 60, 'Who built the Red Fort and in which city?', '**Shah Jahan** built the **Red Fort (Lal Qila)** in **Delhi**, completed in 1648, which served as the main residence of Mughal emperors.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00125', 'defence-exam-bank', 'History & Culture', 1, 61, 'What was the ''Doctrine of Lapse'' and who implemented it?', 'The **Doctrine of Lapse**, implemented by Governor-General **Lord Dalhousie**, allowed the British to annex princely states if a ruler died without a natural male heir; it fuelled resentment leading up to 1857.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00126', 'defence-exam-bank', 'History & Culture', 1, 62, 'Which freedom fighter is known for the slogan ''Swaraj is my birthright and I shall have it''?', '**Bal Gangadhar Tilak**, a prominent nationalist leader of the Lal-Bal-Pal trio, gave this famous call, reflecting the assertive phase of the freedom struggle.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00127', 'defence-exam-bank', 'Geography', 2, 0, 'Which is the highest peak in India, and in which mountain range does it lie?', '**Kangchenjunga (8,586 m)**, on the India-Nepal border in Sikkim, is the highest peak located in India, and the third-highest mountain in the world; it lies in the **Himalayas**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00128', 'defence-exam-bank', 'Geography', 2, 1, 'Which is the longest river in India, and where does it originate?', 'The **Ganga**, originating from the **Gangotri Glacier (Gaumukh)** in Uttarakhand, is the longest river flowing entirely within India, with a length of about **2,525 km**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00129', 'defence-exam-bank', 'Geography', 2, 2, 'Where does the river Brahmaputra originate, and by what name is it known in Tibet?', 'The Brahmaputra originates near the **Angsi Glacier in Tibet**, where it is known as the **Yarlung Tsangpo**, before entering India through Arunachal Pradesh.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00130', 'defence-exam-bank', 'Geography', 2, 3, 'Which Indian river is known as the ''Sorrow of Bihar'' due to its devastating floods?', 'The **Kosi River**, notorious for changing its course and causing severe floods in Bihar, is called the ''Sorrow of Bihar''.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00131', 'defence-exam-bank', 'Geography', 2, 4, 'Which is the only major Indian river that flows from south to north before joining the Ganga?', 'The **Son River**, a tributary rising in the Amarkantak plateau, flows generally northward before joining the Ganga near Patna. The Chambal also flows north to join the Yamuna.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00132', 'defence-exam-bank', 'Geography', 2, 5, 'Which two Indian rivers originate from the Amarkantak Plateau and flow in opposite directions?', 'The **Narmada** (flowing west into the Arabian Sea) and the **Son** (flowing northeast to join the Ganga) both originate from the **Amarkantak Plateau** in Madhya Pradesh.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00133', 'defence-exam-bank', 'Geography', 2, 6, 'Into which sea does the Narmada river drain?', 'The **Narmada** drains into the **Arabian Sea** through the Gulf of Khambhat, forming a long estuary, unlike most peninsular rivers that drain into the Bay of Bengal.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00134', 'defence-exam-bank', 'Geography', 2, 7, 'Which Indian desert lies primarily in the state of Rajasthan?', 'The **Thar Desert (Great Indian Desert)**, also extending into Pakistan, lies mainly in **Rajasthan** and parts of Gujarat, Punjab, and Haryana.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00135', 'defence-exam-bank', 'Geography', 2, 8, 'What are the two main mountain passes connecting India and China in Ladakh/Sikkim used historically for trade?', 'The **Nathu La** pass (Sikkim-Tibet) and the **Karakoram Pass** (Ladakh) are key historical trade routes between India and Tibet/China.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00136', 'defence-exam-bank', 'Geography', 2, 9, 'Which Himalayan pass connects Leh in Ladakh with the Kashmir Valley?', 'The **Zoji La pass** connects Srinagar (Kashmir Valley) with Leh (Ladakh), and is a crucial high-altitude route often closed in winter.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00137', 'defence-exam-bank', 'Geography', 2, 10, 'Which is the highest motorable pass in India, situated in Ladakh?', '**Umling La**, in Ladakh at an altitude of about **19,024 feet (5,798 m)**, is recognised as the world''s highest motorable road pass, connected by the Border Roads Organisation (BRO).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00138', 'defence-exam-bank', 'Geography', 2, 11, 'Which plateau covers most of peninsular India between the Narmada and Krishna rivers?', 'The **Deccan Plateau**, a large triangular tableland, covers most of peninsular India between the Satpura/Narmada in the north and the southern tip of the peninsula.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00139', 'defence-exam-bank', 'Geography', 2, 12, 'Which mountain ranges form the western and eastern edges of the Deccan Plateau?', 'The **Western Ghats (Sahyadri)** border the plateau on the west, and the **Eastern Ghats** border it on the east; the Western Ghats are notably higher and more continuous.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00140', 'defence-exam-bank', 'Geography', 2, 13, 'Which is the highest peak in the Western Ghats?', '**Anamudi (2,695 m)**, located in Kerala''s Idukki district, is the highest peak in the Western Ghats and in peninsular India south of the Himalayas.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00141', 'defence-exam-bank', 'Geography', 2, 14, 'Which Indian state has the longest coastline?', '**Gujarat** has the longest coastline among Indian states, at approximately **1,600 km**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00142', 'defence-exam-bank', 'Geography', 2, 15, 'Which Indian Union Territory is composed of a chain of coral islands in the Arabian Sea?', '**Lakshadweep** is India''s smallest Union Territory, made up of coral atolls and islands in the Arabian Sea, with its capital at **Kavaratti**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00143', 'defence-exam-bank', 'Geography', 2, 16, 'Where are the Andaman and Nicobar Islands located, and which strait separates them?', 'The Andaman and Nicobar Islands lie in the **Bay of Bengal**; the **Ten Degree Channel** separates the Andaman group from the Nicobar group.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00144', 'defence-exam-bank', 'Geography', 2, 17, 'Which strait separates India (Tamil Nadu) from Sri Lanka?', 'The **Palk Strait** lies between Tamil Nadu and Sri Lanka''s northern coast, while the **Gulf of Mannar** lies further south between the two countries.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00145', 'defence-exam-bank', 'Geography', 2, 18, 'Which imaginary line demarcates the boundary between India and Pakistan in Jammu & Kashmir established after the 1947-48 war?', 'The **Line of Control (LoC)** demarcates the de facto border in Jammu and Kashmir, originally the ceasefire line established after the 1947-48 war, formalised by the **Shimla Agreement of 1972**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00146', 'defence-exam-bank', 'Geography', 2, 19, 'What is the ''Radcliffe Line''?', 'The **Radcliffe Line**, drawn by Sir Cyril Radcliffe in 1947, demarcates the international border between **India and Pakistan**, and separately between India and Bangladesh in the east.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00147', 'defence-exam-bank', 'Geography', 2, 20, 'What is the ''McMahon Line'' associated with?', 'The **McMahon Line**, drawn in 1914 at the Simla Convention, demarcates the boundary between India (Arunachal Pradesh) and Tibet/China; China does not recognise it, a key source of the India-China border dispute.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00148', 'defence-exam-bank', 'Geography', 2, 21, 'How many states and Union Territories does India currently have?', 'India has **28 states and 8 Union Territories**, following the reorganisation of Jammu & Kashmir into two Union Territories (J&K and Ladakh) in **2019**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00149', 'defence-exam-bank', 'Geography', 2, 22, 'Which is the largest state in India by area?', '**Rajasthan** is the largest Indian state by area, covering about **3.42 lakh sq km**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00150', 'defence-exam-bank', 'Geography', 2, 23, 'Which is the smallest state in India by area?', '**Goa** is the smallest state in India by area, though **Sikkim** has the smallest population among states.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00151', 'defence-exam-bank', 'Geography', 2, 24, 'Which Indian state shares its border with the maximum number of other states?', '**Uttar Pradesh** borders the most states, sharing boundaries with **eight** other states.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00152', 'defence-exam-bank', 'Geography', 2, 25, 'Which is the southernmost point of the Indian mainland?', '**Kanniyakumari**, at the southern tip of Tamil Nadu, is where the Arabian Sea, Bay of Bengal, and Indian Ocean meet; it is the southernmost point of mainland India (Indira Point in the Nicobar Islands is India''s southernmost territorial point).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00153', 'defence-exam-bank', 'Geography', 2, 26, 'Which Indian city lies on the Tropic of Cancer and is known as a key reference for the line''s path across India?', 'The **Tropic of Cancer** passes through eight Indian states including Gujarat, Rajasthan, Madhya Pradesh, Chhattisgarh, Jharkhand, West Bengal, Tripura, and Mizoram.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00154', 'defence-exam-bank', 'Geography', 2, 27, 'What causes the Indian monsoon, broadly speaking?', 'The monsoon is driven by the **differential heating of land and sea**, creating a pressure gradient that draws moisture-laden winds from the Indian Ocean onto the subcontinent, typically from **June to September (southwest monsoon)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00155', 'defence-exam-bank', 'Geography', 2, 28, 'From which direction does India''s monsoon typically retreat, and when?', 'The **northeast (retreating) monsoon** occurs from **October to December**, bringing rainfall mainly to Tamil Nadu and parts of the southeastern coast as winds reverse direction after the southwest monsoon withdraws.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00156', 'defence-exam-bank', 'Geography', 2, 29, 'Which is the wettest place in India (and among the wettest in the world)?', '**Mawsynram** in Meghalaya, followed closely by nearby **Cherrapunji (Sohra)**, receives some of the highest average annual rainfall in the world due to orographic effects on monsoon winds.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00157', 'defence-exam-bank', 'Geography', 2, 30, 'Which type of soil, rich in iron oxide, is predominantly found in the Deccan Plateau and is suited for cotton cultivation?', '**Black soil (regur soil)**, formed from volcanic (basaltic) rock, is rich in iron and lime, retains moisture well, and is ideal for cotton cultivation, hence also called ''black cotton soil''.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00158', 'defence-exam-bank', 'Geography', 2, 31, 'Which soil type, found in the Indo-Gangetic plains, is the most fertile and widely distributed soil in India?', '**Alluvial soil**, deposited by rivers like the Ganga, Brahmaputra, and Indus, covers the Indo-Gangetic plains and is the most extensive and agriculturally important soil type in India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00159', 'defence-exam-bank', 'Geography', 2, 32, 'Which Indian river is referred to as the ''Dakshin Ganga''?', 'The **Godavari River**, the largest peninsular river, originating near Trimbakeshwar in Maharashtra, is called the ''Dakshin Ganga'' (Ganga of the South).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00160', 'defence-exam-bank', 'Geography', 2, 33, 'Which major peninsular river forms the border between Andhra Pradesh and Telangana for part of its course, after rising near Mahabaleshwar?', 'The **Krishna River**, originating near **Mahabaleshwar** in Maharashtra, flows eastward and forms part of the Telangana-Andhra Pradesh boundary before draining into the Bay of Bengal.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00161', 'defence-exam-bank', 'Geography', 2, 34, 'Which major Indian river originates in Karnataka and is a flashpoint of inter-state water disputes with Tamil Nadu?', 'The **Kaveri (Cauvery) River**, originating at Talakaveri in Karnataka''s Western Ghats, has long been a subject of water-sharing disputes between Karnataka and Tamil Nadu.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00162', 'defence-exam-bank', 'Geography', 2, 35, 'What is the significance of the Sundarbans delta?', 'The **Sundarbans**, formed by the Ganga-Brahmaputra delta spanning India (West Bengal) and Bangladesh, is the **largest mangrove forest in the world** and a UNESCO World Heritage Site, home to the Royal Bengal Tiger.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00163', 'defence-exam-bank', 'Geography', 2, 36, 'Which is the largest coral reef system in India?', 'The **Gulf of Mannar**, between Tamil Nadu and Sri Lanka, hosts India''s first Marine Biosphere Reserve with extensive coral reef ecosystems.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00164', 'defence-exam-bank', 'Geography', 2, 37, 'Which is the longest mountain range in the world, and on which continent is it located?', 'The **Andes**, stretching about **7,000 km** along the western coast of South America, is the world''s longest continental mountain range.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00165', 'defence-exam-bank', 'Geography', 2, 38, 'Which is the highest mountain peak in the world, and on which border is it located?', '**Mount Everest (8,849 m)**, located on the **Nepal-China (Tibet) border**, is the highest peak in the world, part of the Himalayan range.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00166', 'defence-exam-bank', 'Geography', 2, 39, 'Which is the longest river in the world?', 'The **Nile River** in Africa, at approximately **6,650 km**, is generally regarded as the world''s longest river, though the Amazon is a close contender by some measurements.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00167', 'defence-exam-bank', 'Geography', 2, 40, 'Which is the largest desert in the world (hot desert)?', 'The **Sahara Desert** in North Africa, covering about **9.2 million sq km**, is the largest hot desert in the world (Antarctica is the largest desert overall, counting cold deserts).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00168', 'defence-exam-bank', 'Geography', 2, 41, 'Which is the largest ocean in the world?', 'The **Pacific Ocean** is the largest and deepest ocean, covering roughly **one-third of the Earth''s surface**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00169', 'defence-exam-bank', 'Geography', 2, 42, 'Which strait connects the Mediterranean Sea to the Atlantic Ocean?', 'The **Strait of Gibraltar** separates Spain (Europe) from Morocco (Africa) and connects the Mediterranean Sea with the Atlantic Ocean.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00170', 'defence-exam-bank', 'Geography', 2, 43, 'Which canal connects the Mediterranean Sea and the Red Sea, significantly shortening the sea route between Europe and Asia?', 'The **Suez Canal**, in Egypt, opened in **1869**, connects the Mediterranean Sea to the Red Sea, avoiding the need to sail around Africa.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00171', 'defence-exam-bank', 'Geography', 2, 44, 'Which canal connects the Atlantic and Pacific Oceans through Central America?', 'The **Panama Canal**, completed in **1914**, cuts through the Isthmus of Panama, connecting the Atlantic and Pacific Oceans.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00172', 'defence-exam-bank', 'Geography', 2, 45, 'Which strait, a critical global chokepoint for oil shipments, lies between Iran and the Arabian Peninsula?', 'The **Strait of Hormuz** connects the Persian Gulf to the Gulf of Oman and the Arabian Sea, and is one of the world''s most strategically important oil-transit chokepoints.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00173', 'defence-exam-bank', 'Geography', 2, 46, 'Which strait separates Malaysia (and Singapore) from the Indonesian island of Sumatra, a vital global shipping route?', 'The **Strait of Malacca** is one of the busiest shipping lanes in the world, linking the Indian Ocean to the South China Sea and Pacific.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00174', 'defence-exam-bank', 'Geography', 2, 47, 'What is the Equator, and how many degrees of latitude does it represent?', 'The **Equator** is the imaginary line at **0° latitude**, equidistant from the North and South Poles, dividing the Earth into the Northern and Southern Hemispheres.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00175', 'defence-exam-bank', 'Geography', 2, 48, 'What is the Prime Meridian, and through which city does it pass?', 'The **Prime Meridian (0° longitude)** passes through **Greenwich, London**, and serves as the reference line for measuring longitude and determining time zones (GMT).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00176', 'defence-exam-bank', 'Geography', 2, 49, 'How many time zones does mainland India officially observe?', 'India observes a **single time zone**, Indian Standard Time (IST), which is **GMT+5:30**, based on the reference longitude of **82.5° E** passing near Mirzapur, Uttar Pradesh.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00177', 'defence-exam-bank', 'Geography', 2, 50, 'Which is the largest continent by area, and which is the smallest?', '**Asia** is the largest continent by area and population, while **Australia (Oceania)** is the smallest continent.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00178', 'defence-exam-bank', 'Geography', 2, 51, 'Which African mountain is the highest peak on the African continent?', '**Mount Kilimanjaro (5,895 m)** in Tanzania is the highest peak in Africa and the tallest free-standing mountain in the world.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00179', 'defence-exam-bank', 'Geography', 2, 52, 'Which South American mountain is the highest peak outside Asia?', '**Aconcagua (6,961 m)** in Argentina, part of the Andes range, is the highest peak in the Southern and Western Hemispheres.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00180', 'defence-exam-bank', 'Geography', 2, 53, 'What is the ''Ring of Fire''?', 'The **Ring of Fire** is a horseshoe-shaped zone around the **Pacific Ocean basin** characterised by intense seismic and volcanic activity, home to about 75% of the world''s active volcanoes.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00181', 'defence-exam-bank', 'Geography', 2, 54, 'What causes earthquakes along plate boundaries, according to plate tectonic theory?', 'Earthquakes occur due to the **sudden release of energy** from stress built up by the movement of **tectonic plates** along faults, especially at convergent, divergent, and transform plate boundaries.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00182', 'defence-exam-bank', 'Geography', 2, 55, 'Which Indian biosphere reserve, spread across Madhya Pradesh and adjoining states, is the largest in India?', 'The **Nilgiri Biosphere Reserve**, spanning Tamil Nadu, Karnataka, and Kerala, is the first and one of the largest biosphere reserves in India, part of the Western Ghats.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00183', 'defence-exam-bank', 'Geography', 2, 56, 'Which national park in Assam is known for its population of the one-horned rhinoceros?', '**Kaziranga National Park** in Assam, a UNESCO World Heritage Site, is renowned for hosting the largest population of the **one-horned rhinoceros**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00184', 'defence-exam-bank', 'Geography', 2, 57, 'Which national park, spread across Madhya Pradesh, is one of India''s largest tiger reserves and inspired Kipling''s ''The Jungle Book''?', '**Kanha National Park** in Madhya Pradesh is believed to have inspired the setting of Rudyard Kipling''s ''The Jungle Book'', and is a major tiger reserve under Project Tiger.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00185', 'defence-exam-bank', 'Geography', 2, 58, 'When was ''Project Tiger'' launched in India, and what is its objective?', '**Project Tiger** was launched in **1973** to protect the Bengal tiger and its habitat through a network of tiger reserves across India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00186', 'defence-exam-bank', 'Geography', 2, 59, 'Which gulf lies between the Kathiawar and Kutch peninsulas of Gujarat?', 'The **Gulf of Kutch** lies to the north of the Kathiawar Peninsula, while the **Gulf of Khambhat (Cambay)** lies to its south-east, both in Gujarat.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00187', 'defence-exam-bank', 'Geography', 2, 60, 'Which two parallel ranges form the ''Purvanchal'' hill ranges in India''s northeast?', 'The **Purvanchal ranges**, including the **Patkai, Naga, Mizo, and Manipur hills**, form the eastern extension of the Himalayas along India''s border with Myanmar.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00188', 'defence-exam-bank', 'Geography', 2, 61, 'Which Indian mountain range lies between the Narmada and Tapi rivers?', 'The **Satpura Range** lies between the Narmada and Tapi river valleys, running through Madhya Pradesh, Maharashtra, and Gujarat.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00189', 'defence-exam-bank', 'Polity & Economy', 3, 0, 'When did the Constitution of India come into force?', 'The Constitution of India came into force on **26 January 1950**, a date chosen to commemorate the 1930 ''Purna Swaraj'' declaration; this day is celebrated as **Republic Day**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00190', 'defence-exam-bank', 'Polity & Economy', 3, 1, 'Who was the Chairman of the Constituent Assembly''s Drafting Committee?', '**Dr. B.R. Ambedkar** chaired the **Drafting Committee**, formed on 29 August 1947, and is widely regarded as the chief architect of the Constitution.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00191', 'defence-exam-bank', 'Polity & Economy', 3, 2, 'How long did the Constituent Assembly take to draft the Constitution of India?', 'The Constituent Assembly took **2 years, 11 months, and 18 days** to draft the Constitution, from **9 December 1946 to 26 November 1949** (the date of adoption).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00192', 'defence-exam-bank', 'Polity & Economy', 3, 3, 'From which country''s constitution did India borrow the concept of Fundamental Rights?', 'India borrowed the concept of **Fundamental Rights** mainly from the **Constitution of the United States of America**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00193', 'defence-exam-bank', 'Polity & Economy', 3, 4, 'From which country''s constitution did India borrow the Directive Principles of State Policy?', 'The **Directive Principles of State Policy (DPSP)** were borrowed from the **Irish Constitution (Constitution of Ireland)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00194', 'defence-exam-bank', 'Polity & Economy', 3, 5, 'From which country did India borrow the parliamentary form of government?', 'India adopted the **parliamentary system of government**, including the concept of a responsible executive, from the **United Kingdom (Britain)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00195', 'defence-exam-bank', 'Polity & Economy', 3, 6, 'How many Fundamental Rights were originally provided in the Constitution, and how many remain today?', 'Originally, the Constitution provided **seven Fundamental Rights**; the **Right to Property** was removed from Part III by the **44th Amendment (1978)** and made a legal right under Article 300-A, leaving **six Fundamental Rights** today.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00196', 'defence-exam-bank', 'Polity & Economy', 3, 7, 'Which Article of the Constitution deals with the Right to Constitutional Remedies?', '**Article 32** guarantees the Right to Constitutional Remedies, allowing citizens to move the Supreme Court directly for enforcement of Fundamental Rights; Dr. Ambedkar called it the **''heart and soul'' of the Constitution**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00197', 'defence-exam-bank', 'Polity & Economy', 3, 8, 'Which Article abolishes untouchability in India?', '**Article 17** abolishes ''untouchability'' in any form and forbids its practice, making it an offence punishable by law.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00198', 'defence-exam-bank', 'Polity & Economy', 3, 9, 'Which part of the Constitution contains the Directive Principles of State Policy?', 'The **Directive Principles of State Policy** are contained in **Part IV (Articles 36-51)** of the Constitution; though non-justiciable, they guide governance.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00199', 'defence-exam-bank', 'Polity & Economy', 3, 10, 'What are Fundamental Duties, and which amendment introduced them?', '**Fundamental Duties**, listed in **Article 51-A (Part IVA)**, were added by the **42nd Amendment Act, 1976**, based on recommendations of the **Swaran Singh Committee**; originally ten duties, an eleventh was added in 2002.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00200', 'defence-exam-bank', 'Polity & Economy', 3, 11, 'Which Amendment is known as the ''Mini Constitution'' due to its wide-ranging changes?', 'The **42nd Amendment Act, 1976** is called the ''Mini Constitution'' for making extensive changes, including adding ''Socialist'', ''Secular'', and ''Integrity'' to the Preamble.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00201', 'defence-exam-bank', 'Polity & Economy', 3, 12, 'What is the minimum age to become the President of India?', 'A candidate must be at least **35 years old** and a citizen of India to be eligible for the office of President.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00202', 'defence-exam-bank', 'Polity & Economy', 3, 13, 'What is the term of office of the President of India?', 'The President holds office for a term of **five years**, and is eligible for re-election.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00203', 'defence-exam-bank', 'Polity & Economy', 3, 14, 'Who elects the President of India?', 'The President is elected by an **Electoral College** consisting of elected members of both Houses of Parliament and elected members of the **Legislative Assemblies of states and Union Territories (Delhi and Puducherry)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00204', 'defence-exam-bank', 'Polity & Economy', 3, 15, 'Under which Article can the President of India be impeached, and on what ground?', 'Under **Article 61**, the President can be impeached only on the ground of **''violation of the Constitution''**, through a process requiring a resolution passed by a two-thirds majority in both Houses of Parliament.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00205', 'defence-exam-bank', 'Polity & Economy', 3, 16, 'Who appoints the Prime Minister of India?', 'The **President of India** appoints the Prime Minister, usually the leader of the party or coalition commanding a majority in the **Lok Sabha**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00206', 'defence-exam-bank', 'Polity & Economy', 3, 17, 'What is the minimum age requirement to contest elections to the Lok Sabha?', 'A candidate must be at least **25 years old** to contest elections to the **Lok Sabha** (House of the People).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00207', 'defence-exam-bank', 'Polity & Economy', 3, 18, 'What is the minimum age requirement to contest elections to the Rajya Sabha?', 'A candidate must be at least **30 years old** to contest elections to the **Rajya Sabha** (Council of States).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00208', 'defence-exam-bank', 'Polity & Economy', 3, 19, 'What is the maximum strength of the Lok Sabha as envisaged by the Constitution?', 'The Constitution envisages a maximum strength of **552 members** for the Lok Sabha: up to 530 from states, 20 from Union Territories, though the actual composition is periodically revised by law.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00209', 'defence-exam-bank', 'Polity & Economy', 3, 20, 'Is the Rajya Sabha subject to dissolution?', 'No. The **Rajya Sabha is a permanent body** and is not subject to dissolution; **one-third of its members retire every two years**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00210', 'defence-exam-bank', 'Polity & Economy', 3, 21, 'What is a ''Money Bill'' and which House has exclusive authority over it?', 'A **Money Bill**, defined under **Article 110**, deals exclusively with taxation, borrowing, or expenditure from the Consolidated Fund; it can only be introduced in the **Lok Sabha**, and the Rajya Sabha cannot amend or reject it, only recommend changes.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00211', 'defence-exam-bank', 'Polity & Economy', 3, 22, 'Who is the ex-officio Chairman of the Rajya Sabha?', 'The **Vice President of India** serves as the ex-officio **Chairman of the Rajya Sabha**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00212', 'defence-exam-bank', 'Polity & Economy', 3, 23, 'Who appoints the Chief Justice and other judges of the Supreme Court of India?', 'The **President of India** appoints the Chief Justice and other judges of the Supreme Court, based on recommendations of the **Collegium system** comprising senior judges.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00213', 'defence-exam-bank', 'Polity & Economy', 3, 24, 'What is the retirement age for judges of the Supreme Court and High Courts?', 'Supreme Court judges retire at the age of **65 years**, while High Court judges retire at **62 years**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00214', 'defence-exam-bank', 'Polity & Economy', 3, 25, 'What is the concept of ''Judicial Review'' in the Indian Constitution?', '**Judicial Review** is the power of courts, especially the Supreme Court, to examine the constitutionality of legislative and executive actions and **strike down laws that violate the Constitution**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00215', 'defence-exam-bank', 'Polity & Economy', 3, 26, 'What was established by the landmark Kesavananda Bharati case (1973)?', 'The Supreme Court, in **Kesavananda Bharati v. State of Kerala (1973)**, propounded the **''Basic Structure Doctrine''**, holding that Parliament cannot amend the Constitution so as to alter its basic structure.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00216', 'defence-exam-bank', 'Polity & Economy', 3, 27, 'Which constitutional body conducts elections to the Parliament, state legislatures, and offices of President and Vice President?', 'The **Election Commission of India (ECI)**, an independent constitutional body established under **Article 324**, conducts these elections; it currently functions with a Chief Election Commissioner and two Election Commissioners.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00217', 'defence-exam-bank', 'Polity & Economy', 3, 28, 'Which amendment granted constitutional status to Panchayati Raj institutions?', 'The **73rd Constitutional Amendment Act, 1992** granted constitutional status to **Panchayati Raj Institutions (rural local self-government)**, adding Part IX to the Constitution.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00218', 'defence-exam-bank', 'Polity & Economy', 3, 29, 'Which amendment granted constitutional status to urban local bodies (municipalities)?', 'The **74th Constitutional Amendment Act, 1992** granted constitutional status to **urban local bodies (Nagarpalikas)**, adding Part IXA to the Constitution.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00219', 'defence-exam-bank', 'Polity & Economy', 3, 30, 'What is the three-tier structure of the Panchayati Raj system?', 'The Panchayati Raj system has three tiers: the **Gram Panchayat** at the village level, the **Panchayat Samiti (Block)** at the intermediate level, and the **Zila Parishad** at the district level.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00220', 'defence-exam-bank', 'Polity & Economy', 3, 31, 'What body replaced the Planning Commission of India in 2015?', 'The **NITI Aayog (National Institution for Transforming India)** replaced the Planning Commission on **1 January 2015**, serving as a policy think tank rather than an allocator of funds.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00221', 'defence-exam-bank', 'Polity & Economy', 3, 32, 'When were India''s economic reforms (liberalisation, privatisation, globalisation - LPG) initiated, and under whose finance ministership?', 'India''s economic reforms began in **1991** amid a balance-of-payments crisis, led by Finance Minister **Dr. Manmohan Singh** under Prime Minister **P.V. Narasimha Rao**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00222', 'defence-exam-bank', 'Polity & Economy', 3, 33, 'What is the Goods and Services Tax (GST), and when was it implemented?', '**GST**, implemented on **1 July 2017**, is a unified indirect tax that subsumed multiple central and state taxes, based on the principle of ''one nation, one tax''.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00223', 'defence-exam-bank', 'Polity & Economy', 3, 34, 'Which body recommends the distribution of tax revenues between the Union and the States?', 'The **Finance Commission**, constituted every five years under **Article 280**, recommends the distribution of net tax proceeds between the Centre and the states.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00224', 'defence-exam-bank', 'Polity & Economy', 3, 35, 'What is ''Fiscal Deficit''?', '**Fiscal deficit** is the difference between the government''s **total expenditure and total revenue (excluding borrowings)**, indicating the total borrowing requirement of the government.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00225', 'defence-exam-bank', 'Polity & Economy', 3, 36, 'What is ''repo rate'', and which institution sets it?', 'The **repo rate** is the interest rate at which the **Reserve Bank of India (RBI)** lends short-term funds to commercial banks; it is a key tool of monetary policy to control inflation and liquidity.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00226', 'defence-exam-bank', 'Polity & Economy', 3, 37, 'What is the function of the Monetary Policy Committee (MPC)?', 'The **Monetary Policy Committee**, set up in 2016 under the RBI, is responsible for fixing the **benchmark policy interest rate (repo rate)** to maintain price stability while supporting growth.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00227', 'defence-exam-bank', 'Polity & Economy', 3, 38, 'What was the main objective of India''s First Five-Year Plan (1951-56)?', 'The **First Five-Year Plan (1951-56)**, based on the **Harrod-Domar model**, focused primarily on the **agricultural sector**, including irrigation and dam projects like Bhakra Nangal.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00228', 'defence-exam-bank', 'Polity & Economy', 3, 39, 'Which Five-Year Plan focused on rapid industrialisation, based on the Mahalanobis model?', 'The **Second Five-Year Plan (1956-61)**, based on the **P.C. Mahalanobis model**, emphasised rapid **industrialisation**, particularly heavy and basic industries.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00229', 'defence-exam-bank', 'Polity & Economy', 3, 40, 'What is GDP (Gross Domestic Product)?', '**GDP** is the **total monetary value of all final goods and services produced** within a country''s borders in a specific time period, used as a key indicator of economic activity and growth.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00230', 'defence-exam-bank', 'Polity & Economy', 3, 41, 'What is the difference between GDP and GNP?', '**GDP** measures output produced **within a country''s territory**, while **GNP (Gross National Product)** measures output produced by a country''s **residents/nationals**, including income earned abroad, excluding income earned by foreigners domestically.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00231', 'defence-exam-bank', 'Polity & Economy', 3, 42, 'What is ''disinvestment'' in the context of the Indian economy?', '**Disinvestment** refers to the **sale or liquidation of government stake/equity in public sector undertakings (PSUs)**, aimed at raising revenue and improving efficiency.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00232', 'defence-exam-bank', 'Polity & Economy', 3, 43, 'What is the ''Insolvency and Bankruptcy Code (IBC)'', and when was it enacted?', 'The **IBC, 2016** provides a time-bound process for resolving insolvency of companies and individuals, consolidating earlier fragmented laws on corporate debt resolution.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00233', 'defence-exam-bank', 'Polity & Economy', 3, 44, 'What are the two Houses of the Indian Parliament?', 'The Indian Parliament is **bicameral**, comprising the **Lok Sabha (House of the People)**, the lower house, and the **Rajya Sabha (Council of States)**, the upper house, along with the President.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00234', 'defence-exam-bank', 'Polity & Economy', 3, 45, 'What is the ''Anti-Defection Law'' and which schedule of the Constitution contains it?', 'The **Anti-Defection Law**, added by the **52nd Amendment (1985)**, is contained in the **Tenth Schedule** of the Constitution, disqualifying legislators who defect from their party.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00235', 'defence-exam-bank', 'Polity & Economy', 3, 46, 'What is a ''Writ'' and name the five types of writs the Supreme Court/High Courts can issue?', 'A **writ** is a formal order by a court to enforce rights. The five types are **Habeas Corpus, Mandamus, Prohibition, Certiorari, and Quo-Warranto**, issued under Articles 32 and 226.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00236', 'defence-exam-bank', 'Polity & Economy', 3, 47, 'What does the writ of ''Habeas Corpus'' mean?', '**Habeas Corpus** (''you may have the body'') is a writ directing that a detained person be **produced before the court** to determine whether the detention is lawful.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00237', 'defence-exam-bank', 'Polity & Economy', 3, 48, 'Which schedule of the Constitution deals with the allocation of seats in the Rajya Sabha to states?', 'The **Fourth Schedule** of the Constitution allocates seats in the **Rajya Sabha** to states and Union Territories.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00238', 'defence-exam-bank', 'Polity & Economy', 3, 49, 'Which schedule of the Constitution contains the list of recognised languages?', 'The **Eighth Schedule** of the Constitution lists the **officially recognised languages of India**, currently **22 languages**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00239', 'defence-exam-bank', 'Polity & Economy', 3, 50, 'What are the three Lists under the Seventh Schedule that divide legislative powers between the Union and States?', 'The Seventh Schedule divides subjects into the **Union List** (Centre''s exclusive domain, e.g. defence), the **State List** (states'' exclusive domain, e.g. police), and the **Concurrent List** (both can legislate, e.g. education).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00240', 'defence-exam-bank', 'Polity & Economy', 3, 51, 'Who is the head of the Union Public Service Commission (UPSC), and what is its main function?', 'The UPSC is headed by a **Chairman**, appointed by the President, and conducts recruitment examinations for **All India Services and Central Civil Services**, such as the Civil Services Examination, NDA, and CDS exams.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00241', 'defence-exam-bank', 'Polity & Economy', 3, 52, 'What is the Comptroller and Auditor General (CAG) of India responsible for?', 'The **CAG**, established under Article 148, audits the accounts of the **Union and State Governments** and is described as the ''guardian of the public purse''.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00242', 'defence-exam-bank', 'Polity & Economy', 3, 53, 'What is the National Human Rights Commission (NHRC)?', 'The **NHRC**, a statutory body established in **1993** under the Protection of Human Rights Act, investigates violations of human rights and recommends remedial measures.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00243', 'defence-exam-bank', 'Polity & Economy', 3, 54, 'What is the function of the Attorney General of India?', 'The **Attorney General** is the **highest law officer** of the country, appointed by the President, who advises the Government of India on legal matters and represents it in the Supreme Court.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00244', 'defence-exam-bank', 'Polity & Economy', 3, 55, 'What is a ''Hung Parliament/Assembly''?', 'A **hung assembly or parliament** occurs when **no single party or pre-poll coalition secures an absolute majority** of seats, often leading to coalition governments.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00245', 'defence-exam-bank', 'Polity & Economy', 3, 56, 'Which amendment lowered the voting age in India from 21 to 18 years?', 'The **61st Constitutional Amendment Act, 1988** lowered the voting age from **21 to 18 years**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00246', 'defence-exam-bank', 'Polity & Economy', 3, 57, 'What is the ''No Confidence Motion'' in Indian parliamentary procedure?', 'A **No-Confidence Motion**, moved only in the **Lok Sabha**, is used to test whether the Council of Ministers continues to enjoy the confidence of the House; if it passes, the government must resign.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00247', 'defence-exam-bank', 'Polity & Economy', 3, 58, 'What is ''Zero Hour'' in Indian parliamentary proceedings?', '**Zero Hour** is an informal parliamentary device, not mentioned in the Rules of Procedure, during which members can raise matters of urgent public importance, typically starting at **12 noon**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00248', 'defence-exam-bank', 'Polity & Economy', 3, 59, 'What is the significance of Article 370, and what happened to it in 2019?', '**Article 370** granted special autonomous status to Jammu & Kashmir; it was **effectively abrogated in August 2019**, and the state was reorganised into the Union Territories of **Jammu & Kashmir and Ladakh**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00249', 'defence-exam-bank', 'Polity & Economy', 3, 60, 'What is the ''Preamble'' of the Indian Constitution often described as?', 'The **Preamble** is often called the **''identity card'' or ''soul'' of the Constitution**, summarising its guiding philosophy as a **''Sovereign, Socialist, Secular, Democratic Republic''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00250', 'defence-exam-bank', 'Polity & Economy', 3, 61, 'Can the Preamble of the Constitution be amended?', 'Yes, in **Kesavananda Bharati (1973)**, the Supreme Court held the Preamble can be amended under Article 368, but **not so as to alter its basic structure**; it has been amended once, by the 42nd Amendment (1976).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00251', 'defence-exam-bank', 'General Science', 4, 0, 'What is Newton''s First Law of Motion also known as?', 'Newton''s First Law is known as the **Law of Inertia**, stating that a body remains at rest or in uniform motion unless acted upon by an **external unbalanced force**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00252', 'defence-exam-bank', 'General Science', 4, 1, 'State Newton''s Second Law of Motion and its mathematical form.', 'Newton''s Second Law states that the **rate of change of momentum** of a body is directly proportional to the applied force, expressed as `F = ma` (force equals mass times acceleration).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00253', 'defence-exam-bank', 'General Science', 4, 2, 'What does Newton''s Third Law of Motion state?', 'It states that **''for every action, there is an equal and opposite reaction''**, meaning forces always occur in action-reaction pairs acting on different bodies.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00254', 'defence-exam-bank', 'General Science', 4, 3, 'What is the SI unit of force?', 'The SI unit of force is the **Newton (N)**, defined as the force required to give a mass of 1 kg an acceleration of 1 m/s².', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00255', 'defence-exam-bank', 'General Science', 4, 4, 'What is the SI unit of electric current?', 'The SI unit of electric current is the **Ampere (A)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00256', 'defence-exam-bank', 'General Science', 4, 5, 'What is the SI unit of power, and how is it related to work?', 'The SI unit of power is the **Watt (W)**, defined as **one joule of work done per second**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00257', 'defence-exam-bank', 'General Science', 4, 6, 'What is the acceleration due to gravity on Earth, approximately?', 'The standard acceleration due to gravity on Earth''s surface is approximately **9.8 m/s² (often taken as 9.81 m/s²)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00258', 'defence-exam-bank', 'General Science', 4, 7, 'What is the speed of light in a vacuum?', 'The speed of light in vacuum is approximately **3 × 10⁸ metres per second (about 3,00,000 km/s)**, a universal constant denoted by `c`.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00259', 'defence-exam-bank', 'General Science', 4, 8, 'What is the principle behind the working of a simple periscope?', 'A periscope works on the principle of **reflection of light**, using two plane mirrors (or prisms) placed parallel to each other at 45° to redirect light and view objects above the line of sight.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00260', 'defence-exam-bank', 'General Science', 4, 9, 'What is the phenomenon responsible for the blue colour of the sky?', 'The blue colour of the sky is due to **Rayleigh scattering**, where shorter wavelength blue light is scattered more by atmospheric molecules than longer wavelength red light.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00261', 'defence-exam-bank', 'General Science', 4, 10, 'What is the normal range of human body temperature in Celsius?', 'Normal human body temperature is approximately **37°C (98.6°F)**, though it can vary slightly between individuals.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00262', 'defence-exam-bank', 'General Science', 4, 11, 'What is the function of red blood cells (erythrocytes) in the human body?', '**Red blood cells** transport **oxygen** from the lungs to body tissues and carry carbon dioxide back to the lungs, using the protein **haemoglobin**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00263', 'defence-exam-bank', 'General Science', 4, 12, 'What is the function of white blood cells (leukocytes)?', '**White blood cells** are part of the **immune system**, defending the body against infections, pathogens, and foreign substances.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00264', 'defence-exam-bank', 'General Science', 4, 13, 'How many chambers does the human heart have?', 'The human heart has **four chambers**: two upper chambers called **atria** and two lower chambers called **ventricles**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00265', 'defence-exam-bank', 'General Science', 4, 14, 'What is the normal pulse rate (heart rate) of a healthy adult at rest?', 'The normal resting heart rate for a healthy adult is approximately **60-100 beats per minute**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00266', 'defence-exam-bank', 'General Science', 4, 15, 'Which organ in the human body is primarily responsible for detoxification (filtering toxins from blood)?', 'The **liver** is the body''s primary detoxification organ, also responsible for producing bile, storing glycogen, and metabolising nutrients.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00267', 'defence-exam-bank', 'General Science', 4, 16, 'What is the function of the kidneys in the human body?', 'The **kidneys** filter blood to remove waste products and excess water, forming **urine**, while regulating electrolyte balance and blood pressure.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00268', 'defence-exam-bank', 'General Science', 4, 17, 'What is the basic structural and functional unit of the nervous system?', 'The **neuron (nerve cell)** is the basic structural and functional unit of the nervous system, transmitting electrical and chemical signals.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00269', 'defence-exam-bank', 'General Science', 4, 18, 'Which vitamin deficiency causes the disease scurvy?', 'A deficiency of **Vitamin C (ascorbic acid)** causes **scurvy**, characterised by bleeding gums and poor wound healing.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00270', 'defence-exam-bank', 'General Science', 4, 19, 'Which vitamin deficiency causes night blindness?', 'A deficiency of **Vitamin A (retinol)** causes **night blindness (nyctalopia)** and other eye disorders.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00271', 'defence-exam-bank', 'General Science', 4, 20, 'Which vitamin deficiency causes rickets in children?', 'A deficiency of **Vitamin D** causes **rickets** in children, characterised by weak and deformed bones due to poor calcium absorption.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00272', 'defence-exam-bank', 'General Science', 4, 21, 'Which vitamin is essential for blood clotting?', '**Vitamin K** plays a key role in **blood clotting (coagulation)** by helping synthesise clotting factors in the liver.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00273', 'defence-exam-bank', 'General Science', 4, 22, 'What is the chemical formula of common salt?', 'Common salt is **sodium chloride**, with the chemical formula **NaCl**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00274', 'defence-exam-bank', 'General Science', 4, 23, 'What is the pH value of a neutral solution such as pure water?', 'A neutral solution has a **pH of 7**; values below 7 indicate acidity, and values above 7 indicate alkalinity (basicity).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00275', 'defence-exam-bank', 'General Science', 4, 24, 'What is the chemical formula of baking soda?', 'Baking soda is **sodium bicarbonate**, with the chemical formula **NaHCO₃**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00276', 'defence-exam-bank', 'General Science', 4, 25, 'What is the most abundant gas in the Earth''s atmosphere?', '**Nitrogen** is the most abundant gas in Earth''s atmosphere, making up about **78%** of its volume, followed by oxygen at about **21%**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00277', 'defence-exam-bank', 'General Science', 4, 26, 'Which gas is commonly known as ''laughing gas'', used as an anaesthetic?', '**Nitrous oxide (N₂O)** is commonly called ''laughing gas'' and is used as a mild anaesthetic and analgesic.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00278', 'defence-exam-bank', 'General Science', 4, 27, 'What is the chemical symbol for gold, and from which Latin word is it derived?', 'Gold''s chemical symbol is **Au**, derived from the Latin word **''aurum''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00279', 'defence-exam-bank', 'General Science', 4, 28, 'What is the atomic number of hydrogen, and how many protons does it have?', 'Hydrogen has an **atomic number of 1**, meaning it has **one proton** in its nucleus; it is the lightest and most abundant element in the universe.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00280', 'defence-exam-bank', 'General Science', 4, 29, 'Who is credited with developing the modern Periodic Table based on atomic number?', '**Henry Moseley** refined the periodic table by ordering elements by **atomic number**; the earlier version by **Dmitri Mendeleev** (1869) had ordered elements by atomic mass.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00281', 'defence-exam-bank', 'General Science', 4, 30, 'What are isotopes?', '**Isotopes** are atoms of the same element having the **same number of protons but different numbers of neutrons**, giving them different atomic masses while retaining the same chemical properties.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00282', 'defence-exam-bank', 'General Science', 4, 31, 'What is the process by which green plants synthesise food using sunlight called?', '**Photosynthesis** is the process by which green plants, algae, and some bacteria convert **carbon dioxide and water into glucose and oxygen** using sunlight and chlorophyll.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00283', 'defence-exam-bank', 'General Science', 4, 32, 'What is the green pigment in plants responsible for photosynthesis called?', '**Chlorophyll** is the green pigment found in chloroplasts, essential for absorbing light energy during photosynthesis.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00284', 'defence-exam-bank', 'General Science', 4, 33, 'What is the process of respiration in living organisms?', '**Respiration** is the metabolic process of breaking down glucose to release energy, consuming oxygen and producing **carbon dioxide and water** (in aerobic respiration).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00285', 'defence-exam-bank', 'General Science', 4, 34, 'What is osmosis?', '**Osmosis** is the movement of water molecules from a region of **lower solute concentration to higher solute concentration** through a semi-permeable membrane.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00286', 'defence-exam-bank', 'General Science', 4, 35, 'What is the function of the pancreas in the human digestive system?', 'The **pancreas** secretes digestive enzymes into the small intestine and produces the hormones **insulin and glucagon** to regulate blood sugar levels.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00287', 'defence-exam-bank', 'General Science', 4, 36, 'Which hormone deficiency causes diabetes mellitus?', 'A deficiency or ineffective use of **insulin**, produced by the pancreas, causes **diabetes mellitus**, leading to elevated blood glucose levels.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00288', 'defence-exam-bank', 'General Science', 4, 37, 'What is the function of DNA in living organisms?', '**DNA (deoxyribonucleic acid)** carries the **genetic information** required for the development, functioning, and reproduction of living organisms.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00289', 'defence-exam-bank', 'General Science', 4, 38, 'Who discovered the double-helix structure of DNA?', '**James Watson and Francis Crick** described the **double-helix structure of DNA in 1953**, building on X-ray diffraction data from Rosalind Franklin and Maurice Wilkins.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00290', 'defence-exam-bank', 'General Science', 4, 39, 'What is the basic unit of heredity called?', 'A **gene** is the basic unit of heredity, consisting of a segment of DNA that codes for a specific protein or trait.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00291', 'defence-exam-bank', 'General Science', 4, 40, 'Who is known as the father of modern genetics?', '**Gregor Mendel**, an Austrian monk, is known as the **''Father of Genetics''** for his experiments on pea plants establishing the laws of inheritance.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00292', 'defence-exam-bank', 'General Science', 4, 41, 'What type of mirror is used in vehicle rear-view/side mirrors, and why?', 'A **convex mirror** is used in vehicle side mirrors because it provides a **wider field of view**, though it forms a smaller, virtual image.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00293', 'defence-exam-bank', 'General Science', 4, 42, 'What type of lens is used to correct myopia (short-sightedness)?', 'A **concave (diverging) lens** is used to correct **myopia**, as it diverges light rays before they reach the eye, allowing the image to focus correctly on the retina.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00294', 'defence-exam-bank', 'General Science', 4, 43, 'What type of lens is used to correct hypermetropia (long-sightedness)?', 'A **convex (converging) lens** is used to correct **hypermetropia (far-sightedness)**, helping focus light rays onto the retina.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00295', 'defence-exam-bank', 'General Science', 4, 44, 'What is the unit used to measure the power of a lens?', 'The power of a lens is measured in **dioptres (D)**, defined as the reciprocal of the focal length in metres.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00296', 'defence-exam-bank', 'General Science', 4, 45, 'What is sound, and in which medium does it travel fastest among solids, liquids, and gases?', '**Sound** is a mechanical wave requiring a medium to travel; it travels **fastest in solids**, slower in liquids, and slowest in gases, due to differences in molecular density and elasticity.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00297', 'defence-exam-bank', 'General Science', 4, 46, 'What is the normal range of audible sound frequency for the human ear?', 'The human ear can typically perceive sound frequencies in the range of **20 Hz to 20,000 Hz (20 kHz)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00298', 'defence-exam-bank', 'General Science', 4, 47, 'What is the Doppler Effect?', 'The **Doppler Effect** is the apparent change in frequency (pitch) of a wave due to the **relative motion between the source and the observer**, such as the changing pitch of a passing ambulance siren.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00299', 'defence-exam-bank', 'General Science', 4, 48, 'What is the chemical name and formula for ''washing soda''?', 'Washing soda is **sodium carbonate decahydrate**, with the formula **Na₂CO₃·10H₂O**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00300', 'defence-exam-bank', 'General Science', 4, 49, 'What is an alloy, and give an example used in construction?', 'An **alloy** is a homogeneous mixture of two or more metals (or a metal and non-metal) to enhance desirable properties; **steel (iron and carbon)** is a widely used alloy in construction.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00301', 'defence-exam-bank', 'General Science', 4, 50, 'What is the composition of stainless steel that makes it corrosion-resistant?', '**Stainless steel** is an alloy of **iron, chromium (at least 10.5%), and often nickel**, where chromium forms a protective oxide layer preventing rust.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00302', 'defence-exam-bank', 'General Science', 4, 51, 'What is the main component of natural gas used as fuel?', '**Methane (CH₄)** is the main component of natural gas.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00303', 'defence-exam-bank', 'General Science', 4, 52, 'What causes rusting of iron, and what is the chemical name of rust?', 'Rusting occurs due to the reaction of **iron with oxygen and moisture**, forming **hydrated iron(III) oxide (Fe₂O₃·xH₂O)**, commonly called rust.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00304', 'defence-exam-bank', 'General Science', 4, 53, 'What is the function of antibodies in the human body?', '**Antibodies**, produced by white blood cells (B-lymphocytes), are proteins that identify and neutralise foreign invaders such as **bacteria and viruses**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00305', 'defence-exam-bank', 'General Science', 4, 54, 'What vaccine-preventable disease was declared eradicated globally by the WHO in 1980?', '**Smallpox** was declared eradicated worldwide by the **WHO in 1980**, following a successful global vaccination campaign; it remains the only human disease eradicated this way.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00306', 'defence-exam-bank', 'General Science', 4, 55, 'What causes malaria, and how is it transmitted?', 'Malaria is caused by **Plasmodium parasites**, transmitted through the bite of an infected **female Anopheles mosquito**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00307', 'defence-exam-bank', 'General Science', 4, 56, 'What causes dengue fever, and which mosquito transmits it?', 'Dengue is caused by the **dengue virus**, transmitted primarily by the **Aedes aegypti mosquito**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00308', 'defence-exam-bank', 'General Science', 4, 57, 'What is the function of the ozone layer in the Earth''s atmosphere?', 'The **ozone layer**, located in the stratosphere, absorbs most of the Sun''s harmful **ultraviolet (UV) radiation**, protecting living organisms on Earth.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00309', 'defence-exam-bank', 'General Science', 4, 58, 'What is the greenhouse effect?', 'The **greenhouse effect** is the process by which gases like **carbon dioxide and methane** trap heat in the Earth''s atmosphere, warming the planet''s surface; it is a natural process intensified by human activity.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00310', 'defence-exam-bank', 'General Science', 4, 59, 'What is an exothermic reaction?', 'An **exothermic reaction** is a chemical reaction that **releases energy, usually as heat**, to the surroundings, such as combustion.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00311', 'defence-exam-bank', 'General Science', 4, 60, 'What is the law of conservation of mass in chemistry?', 'The **law of conservation of mass** states that mass can neither be created nor destroyed in a chemical reaction; the **total mass of reactants equals the total mass of products**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00312', 'defence-exam-bank', 'General Science', 4, 61, 'What are the three states of matter commonly studied in classical physics?', 'The three common states of matter are **solid, liquid, and gas**, distinguished by the arrangement and energy of their constituent particles (plasma is often cited as a fourth state).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00313', 'defence-exam-bank', 'Defence & Military Awareness', 5, 0, 'What is the highest rank in the Indian Army, and how many officers have held it?', '**Field Marshal** is the highest rank in the Indian Army, a five-star rank conferred only twice: on **Field Marshal Sam Manekshaw** and **Field Marshal K.M. Cariappa**. It is a ceremonial, non-retiring rank.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00314', 'defence-exam-bank', 'Defence & Military Awareness', 5, 1, 'Who was India''s first Chief of Army Staff (independent India)?', '**General (later Field Marshal) K.M. Cariappa** became the first Indian Commander-in-Chief of the Indian Army on **15 January 1949**, a date now celebrated as **Army Day**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00315', 'defence-exam-bank', 'Defence & Military Awareness', 5, 2, 'Who was India''s first Chief of Defence Staff (CDS)?', '**General Bipin Rawat** became India''s first CDS on **1 January 2020**; he died in a **helicopter crash near Coonoor, Tamil Nadu, in December 2021**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00316', 'defence-exam-bank', 'Defence & Military Awareness', 5, 3, 'What is the role of the Chief of Defence Staff?', 'The **CDS** heads the **Department of Military Affairs**, acts as the Principal Military Adviser to the Defence Minister, and works to promote **jointness and integration** among the Army, Navy, and Air Force, including theaterisation reforms.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00317', 'defence-exam-bank', 'Defence & Military Awareness', 5, 4, 'What is the equivalent Navy rank to a Lieutenant General in the Army?', 'The Navy rank equivalent to **Lieutenant General (Army)** and **Air Marshal (Air Force)** is **Vice Admiral**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00318', 'defence-exam-bank', 'Defence & Military Awareness', 5, 5, 'What is the equivalent Air Force and Navy rank to a Colonel in the Army?', 'A **Colonel (Army)** is equivalent to a **Group Captain (Air Force)** and a **Captain (Navy)**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00319', 'defence-exam-bank', 'Defence & Military Awareness', 5, 6, 'What is the highest field rank typically held by the service chiefs of the Army, Navy, and Air Force?', 'The service chiefs typically hold the ranks of **General (Army)**, **Admiral (Navy)**, and **Air Chief Marshal (Air Force)**, each a four-star rank.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00320', 'defence-exam-bank', 'Defence & Military Awareness', 5, 7, 'Where is the National Defence Academy (NDA) located, and what is unique about it?', 'The **National Defence Academy**, located at **Khadakwasla, Pune**, is the **first tri-service training academy in the world**, where cadets of the Army, Navy, and Air Force train together before specialised training.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00321', 'defence-exam-bank', 'Defence & Military Awareness', 5, 8, 'Where is the Indian Military Academy (IMA) located, and what is its function?', 'The **Indian Military Academy**, located in **Dehradun, Uttarakhand**, trains cadets for commissioning as officers in the **Indian Army**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00322', 'defence-exam-bank', 'Defence & Military Awareness', 5, 9, 'Where is the Indian Naval Academy located?', 'The **Indian Naval Academy (INA)** is located at **Ezhimala, Kerala**, and trains officer cadets for the **Indian Navy**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00323', 'defence-exam-bank', 'Defence & Military Awareness', 5, 10, 'Where is the Air Force Academy located?', 'The **Air Force Academy** is located at **Dundigal, near Hyderabad, Telangana**, and trains officer cadets for the **Indian Air Force**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00324', 'defence-exam-bank', 'Defence & Military Awareness', 5, 11, 'Which training academies prepare graduate entrants for the Army through the Officers Training Academy (OTA)?', 'The **Officers Training Academy** has two campuses, at **Chennai, Tamil Nadu**, and **Gaya, Bihar**, training both men and women graduate entrants for Short Service Commission.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00325', 'defence-exam-bank', 'Defence & Military Awareness', 5, 12, 'What is India''s highest gallantry award, and how many personnel have received it to date?', 'The **Param Vir Chakra (PVC)** is India''s highest wartime gallantry award, awarded **21 times since 1950**, with **14 of those awards given posthumously**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00326', 'defence-exam-bank', 'Defence & Military Awareness', 5, 13, 'Who was the first recipient of the Param Vir Chakra?', '**Major Somnath Sharma**, awarded posthumously for his actions in the **Battle of Badgam (1947-48 Indo-Pak War)**, was the first recipient of the Param Vir Chakra.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00327', 'defence-exam-bank', 'Defence & Military Awareness', 5, 14, 'What is the second-highest gallantry award in India, awarded for acts of conspicuous gallantry in the presence of the enemy?', 'The **Maha Vir Chakra (MVC)** is India''s second-highest wartime gallantry award, ranking below the Param Vir Chakra and above the Vir Chakra.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00328', 'defence-exam-bank', 'Defence & Military Awareness', 5, 15, 'What is the Ashoka Chakra, and how does it compare to the Param Vir Chakra?', 'The **Ashoka Chakra** is India''s highest **peacetime** gallantry award, for the most conspicuous bravery away from the battlefield; it is considered the peacetime equivalent of the Param Vir Chakra.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00329', 'defence-exam-bank', 'Defence & Military Awareness', 5, 16, 'Name the two peacetime gallantry awards that rank below the Ashoka Chakra.', 'The **Kirti Chakra** and the **Shaurya Chakra** rank below the Ashoka Chakra, awarded in descending order for gallantry in peacetime (other than in the face of the enemy).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00330', 'defence-exam-bank', 'Defence & Military Awareness', 5, 17, 'When is ''Kargil Vijay Diwas'' observed, and what does it commemorate?', '**Kargil Vijay Diwas** is observed on **26 July** every year to commemorate India''s victory in the **Kargil War (1999)** against Pakistani intrusions in the Kargil sector of Jammu & Kashmir.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00331', 'defence-exam-bank', 'Defence & Military Awareness', 5, 18, 'What was the Indian military operation in the Kargil War of 1999 called?', 'The Indian military response to the Kargil intrusion was called **''Operation Vijay''**, while the Indian Air Force''s air operations were codenamed **''Operation Safed Sagar''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00332', 'defence-exam-bank', 'Defence & Military Awareness', 5, 19, 'When is Indian Navy Day observed, and what does it commemorate?', '**Navy Day** is observed on **4 December**, commemorating **''Operation Trident''**, the Indian Navy''s successful attack on Karachi harbour during the **1971 Indo-Pak War**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00333', 'defence-exam-bank', 'Defence & Military Awareness', 5, 20, 'When is Indian Air Force Day observed, and why?', '**Air Force Day** is observed on **8 October**, marking the official establishment of the **Indian Air Force in 1932**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00334', 'defence-exam-bank', 'Defence & Military Awareness', 5, 21, 'What was ''Operation Meghdoot'', and what was its significance?', '**Operation Meghdoot (1984)** was the Indian Army''s operation to secure the **Siachen Glacier**, making it the **world''s highest battlefield**; it remains under Indian control to this day.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00335', 'defence-exam-bank', 'Defence & Military Awareness', 5, 22, 'What was ''Operation Cactus'' (1988)?', '**Operation Cactus** was an Indian military intervention in **1988** that airlifted troops to the **Maldives** to foil a coup attempt against President Maumoon Abdul Gayoom, at his government''s request.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00336', 'defence-exam-bank', 'Defence & Military Awareness', 5, 23, 'What was ''Operation Pawan'' (1987-90)?', '**Operation Pawan** was the Indian Peace Keeping Force''s (IPKF) military operation in **Sri Lanka** against the LTTE, aimed at enforcing the Indo-Sri Lanka Accord (1987).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00337', 'defence-exam-bank', 'Defence & Military Awareness', 5, 24, 'What was ''Operation Parakram'' (2001-02)?', '**Operation Parakram** was a large-scale mobilisation of Indian armed forces along the border with Pakistan, launched after the **December 2001 attack on the Indian Parliament**, lasting nearly ten months.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00338', 'defence-exam-bank', 'Defence & Military Awareness', 5, 25, 'What was ''Operation Sindoor'' (2025)?', '**Operation Sindoor** was a tri-service precision-strike operation launched by India on **7 May 2025**, targeting terrorist infrastructure in Pakistan and Pakistan-occupied Kashmir, in response to the **Pahalgam terror attack of 22 April 2025**; a ceasefire understanding followed within days.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00339', 'defence-exam-bank', 'Defence & Military Awareness', 5, 26, 'What was the outcome of the 1971 Indo-Pak War for the eastern front?', 'The **1971 War** resulted in the **liberation of Bangladesh (formerly East Pakistan)**, culminating in the surrender of over **93,000 Pakistani troops at Dhaka on 16 December 1971**, observed annually as **Vijay Diwas**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00340', 'defence-exam-bank', 'Defence & Military Awareness', 5, 27, 'Which war is associated with the annexation of Goa into the Indian Union?', '**Operation Vijay (1961)** was the Indian military action that ended **Portuguese colonial rule in Goa, Daman, and Diu**, integrating them into India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00341', 'defence-exam-bank', 'Defence & Military Awareness', 5, 28, 'What triggered the first Indo-Pak War of 1947-48?', 'The war began after **Pakistani tribal militias and troops invaded Jammu & Kashmir** in October 1947, prompting Maharaja Hari Singh to accede to India, followed by Indian military intervention to repel the invaders.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00342', 'defence-exam-bank', 'Defence & Military Awareness', 5, 29, 'What was the outcome of the Sino-Indian War of 1962?', 'The brief but intense **1962 war**, fought in the Aksai Chin and NEFA (now Arunachal Pradesh) sectors, ended with a **unilateral Chinese ceasefire**, and China retained control of Aksai Chin.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00343', 'defence-exam-bank', 'Defence & Military Awareness', 5, 30, 'What is ''Exercise Malabar'', and which countries participate?', '**Exercise Malabar** is a multilateral naval exercise originally between **India and the USA**, now regularly including **Japan and Australia** (the Quad nations), focused on maritime security cooperation.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00344', 'defence-exam-bank', 'Defence & Military Awareness', 5, 31, 'What is ''Exercise Yudh Abhyas''?', '**Yudh Abhyas** is an annual joint military (army) exercise between **India and the United States**, focused on counter-terrorism and tactical interoperability.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00345', 'defence-exam-bank', 'Defence & Military Awareness', 5, 32, 'What is ''Exercise Indra''?', '**Exercise Indra** is a joint military exercise series between **India and Russia**, covering army, navy, and air force components.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00346', 'defence-exam-bank', 'Defence & Military Awareness', 5, 33, 'What is ''Exercise Varuna''?', '**Exercise Varuna** is a bilateral naval exercise between **India and France**, focused on maritime security and interoperability.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00347', 'defence-exam-bank', 'Defence & Military Awareness', 5, 34, 'What is ''Exercise Garuda Shakti''?', '**Garuda Shakti** is a joint special forces exercise between **India and Indonesia**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00348', 'defence-exam-bank', 'Defence & Military Awareness', 5, 35, 'What is ''Exercise Surya Kiran''?', '**Surya Kiran** is a joint army training exercise between **India and Nepal**, focused on counter-terrorism and jungle warfare.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00349', 'defence-exam-bank', 'Defence & Military Awareness', 5, 36, 'What is ''Cope India''?', '**Cope India** is a bilateral air exercise between the **Indian Air Force and the United States Air Force (USAF)**, focused on air combat tactics and interoperability.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00350', 'defence-exam-bank', 'Defence & Military Awareness', 5, 37, 'What is ''Exercise Vajra Prahar''?', '**Vajra Prahar** is a joint special forces training exercise between **India and the United States**, focused on joint planning and tactical combat.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00351', 'defence-exam-bank', 'Defence & Military Awareness', 5, 38, 'What does DRDO stand for, and what is its primary role?', '**DRDO (Defence Research and Development Organisation)**, under the Ministry of Defence, is responsible for developing **military technology and equipment** for the Indian armed forces, headquartered in New Delhi.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00352', 'defence-exam-bank', 'Defence & Military Awareness', 5, 39, 'What is HAL, and what are its key products?', '**Hindustan Aeronautics Limited (HAL)**, headquartered in **Bengaluru**, designs and manufactures military aircraft and helicopters, including the **Tejas Light Combat Aircraft, Dhruv helicopter, and Su-30MKI** (under licence).', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00353', 'defence-exam-bank', 'Defence & Military Awareness', 5, 40, 'What does BEL stand for, and what does it manufacture?', '**Bharat Electronics Limited (BEL)** is a defence public sector undertaking that manufactures **electronic equipment for the armed forces**, including radars, communication systems, and electronic warfare systems.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00354', 'defence-exam-bank', 'Defence & Military Awareness', 5, 41, 'What is the Tejas, and which organisation developed it?', 'The **Tejas** is an indigenously developed **single-engine, light combat aircraft (LCA)**, designed by the **Aeronautical Development Agency (ADA)** and manufactured by HAL.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00355', 'defence-exam-bank', 'Defence & Military Awareness', 5, 42, 'Which fighter jet did India procure from France, inducted into the IAF starting 2020?', 'The **Rafale**, a twin-engine multirole fighter from **Dassault Aviation (France)**, was inducted into the IAF, with the first squadron based at **Ambala Air Force Station**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00356', 'defence-exam-bank', 'Defence & Military Awareness', 5, 43, 'Which Russian-origin fighter aircraft forms the backbone of the Indian Air Force''s fleet, manufactured under licence by HAL?', 'The **Su-30MKI**, a twin-engine air superiority fighter of Russian origin, forms the mainstay of the IAF, manufactured under licence by **HAL** in India.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00357', 'defence-exam-bank', 'Defence & Military Awareness', 5, 44, 'What is BrahMos, and which countries jointly developed it?', '**BrahMos** is a **supersonic cruise missile**, jointly developed by **India (DRDO) and Russia (NPO Mashinostroyenia)**, named after the rivers Brahmaputra and Moskva.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00358', 'defence-exam-bank', 'Defence & Military Awareness', 5, 45, 'What is the Agni-V missile, and what type of missile is it?', '**Agni-V** is a nuclear-capable, **intercontinental-range ballistic missile (ICBM)** developed by DRDO, with an officially stated range of **over 5,000 km**, capable of striking targets across Asia and parts of Europe and Africa.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00359', 'defence-exam-bank', 'Defence & Military Awareness', 5, 46, 'What is the Prithvi missile series?', 'The **Prithvi** series comprises India''s first indigenously developed **short-range, surface-to-surface ballistic missiles**, developed under the Integrated Guided Missile Development Programme (IGMDP) led by Dr. A.P.J. Abdul Kalam.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00360', 'defence-exam-bank', 'Defence & Military Awareness', 5, 47, 'What is the Akash missile system?', '**Akash** is an indigenously developed **medium-range, surface-to-air missile (SAM)** system designed to defend against aerial threats such as fighter aircraft and cruise missiles.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00361', 'defence-exam-bank', 'Defence & Military Awareness', 5, 48, 'What is the S-400 Triumf, and which country supplies it to India?', 'The **S-400 Triumf** is a long-range **surface-to-air missile defence system** procured by India from **Russia**, designed to intercept aircraft, drones, and missiles at long range; India calls its system ''Sudarshan Chakra''.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00362', 'defence-exam-bank', 'Defence & Military Awareness', 5, 49, 'What is INS Vikrant, and when was it commissioned?', '**INS Vikrant** is India''s first **indigenously built aircraft carrier**, constructed by Cochin Shipyard Limited and commissioned into the Navy on **2 September 2022**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00363', 'defence-exam-bank', 'Defence & Military Awareness', 5, 50, 'What is INS Vikramaditya?', '**INS Vikramaditya** is an aircraft carrier of the Indian Navy, originally the Soviet/Russian carrier ''Admiral Gorshkov'', refitted and commissioned into Indian service in **2013**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00364', 'defence-exam-bank', 'Defence & Military Awareness', 5, 51, 'What is the Arjun Main Battle Tank?', 'The **Arjun** is India''s indigenously developed **Main Battle Tank (MBT)**, developed by DRDO''s Combat Vehicles Research and Development Establishment (CVRDE), inducted into the Indian Army.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00365', 'defence-exam-bank', 'Defence & Military Awareness', 5, 52, 'What is the primary role of the Indian Coast Guard, and when was it established?', 'The **Indian Coast Guard**, established in **1978**, is responsible for **maritime law enforcement, search and rescue, and protection of India''s maritime zones and offshore assets**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00366', 'defence-exam-bank', 'Defence & Military Awareness', 5, 53, 'Which is India''s largest paramilitary force, often deployed for internal security and counter-insurgency?', 'The **Central Reserve Police Force (CRPF)** is India''s largest Central Armed Police Force, tasked with internal security, counter-insurgency, and law-and-order duties.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00367', 'defence-exam-bank', 'Defence & Military Awareness', 5, 54, 'Which force guards India''s border with Pakistan and Bangladesh?', 'The **Border Security Force (BSF)**, raised in **1965**, guards India''s borders with **Pakistan and Bangladesh** during peacetime.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00368', 'defence-exam-bank', 'Defence & Military Awareness', 5, 55, 'Which force is primarily responsible for guarding the Indo-China border?', 'The **Indo-Tibetan Border Police (ITBP)**, raised in **1962**, is primarily responsible for guarding India''s border with **China (Tibet)** in high-altitude terrain.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00369', 'defence-exam-bank', 'Defence & Military Awareness', 5, 56, 'Which is India''s oldest paramilitary force, with roots tracing back to the colonial era?', 'The **Assam Rifles**, with origins dating to **1835**, is the oldest paramilitary force in India, now deployed mainly in the northeastern states under the Ministry of Home Affairs operational control and Army administrative control.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00370', 'defence-exam-bank', 'Defence & Military Awareness', 5, 57, 'Which specialised force is tasked with counter-terrorism and hostage rescue operations in India?', 'The **National Security Guard (NSG)**, raised in **1984**, is a special counter-terrorism force often called the ''Black Cats'' due to their black uniform.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00371', 'defence-exam-bank', 'Defence & Military Awareness', 5, 58, 'Which force is responsible for providing security to industrial undertakings, airports, and metro systems?', 'The **Central Industrial Security Force (CISF)** provides security to key installations like airports, nuclear plants, and metros.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00372', 'defence-exam-bank', 'Defence & Military Awareness', 5, 59, 'What are the seven defence public sector undertakings (DPSUs) that emerged from the corporatisation of the Ordnance Factory Board in 2021?', 'In **October 2021**, the **Ordnance Factory Board** was corporatised into seven new DPSUs, including **Munitions India Limited, Armoured Vehicles Nigam Limited, Advanced Weapons and Equipment India Limited, Troop Comforts Limited, Yantra India Limited, India Optel Limited, and Gliders India Limited**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00373', 'defence-exam-bank', 'Defence & Military Awareness', 5, 60, 'What is the primary objective of India''s ''theaterisation'' military reform initiative?', '**Theaterisation** aims to integrate the Army, Navy, and Air Force into unified **theatre commands** for better jointness, coordination, and operational efficiency, a key priority of the Chief of Defence Staff.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00374', 'defence-exam-bank', 'Defence & Military Awareness', 5, 61, 'What is the significance of the National War Memorial in New Delhi?', 'The **National War Memorial**, inaugurated on **25 February 2019** near India Gate, honours soldiers who sacrificed their lives in wars and operations since independence, listing names on its walls.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00375', 'defence-exam-bank', 'Defence & Military Awareness', 5, 62, 'What is ''Siachen Glacier'' known for in a military context?', 'The **Siachen Glacier**, in the Karakoram range, is the **world''s highest militarised zone**, held by India since Operation Meghdoot (1984), presenting extreme challenges due to altitude and sub-zero temperatures.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00376', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 0, 'Find the next number in the series: 2, 6, 12, 20, 30, ?', 'The series follows the pattern `n(n+1)`: 1×2=2, 2×3=6, 3×4=12, 4×5=20, 5×6=30.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00377', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 1, 'Find the next number in the series: 3, 9, 27, 81, ?', 'Each term is obtained by multiplying the previous term by **3**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00378', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 2, 'Find the next letter in the series: A, C, F, J, O, ?', 'The gap between consecutive letters increases by one each time: +2, +3, +4, +5, so the next gap is +6.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00379', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 3, 'Find the next number in the series: 5, 11, 23, 47, ?', 'Each term follows the rule **''double the previous term and add 1''**: 5×2+1=11, 11×2+1=23, 23×2+1=47.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00380', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 4, 'Find the next number in the series: 7, 13, 25, 49, ?', 'Each term follows the rule **''double the previous term and subtract 1''**: 7×2−1=13, 13×2−1=25, 25×2−1=49.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00381', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 5, 'Find the next number in the series: 1, 2, 4, 7, 11, 16, ?', 'The differences between consecutive terms increase by 1 each time: +1, +2, +3, +4, +5, so the next difference is +6.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00382', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 6, 'Find the next number in the series: 2, 5, 10, 17, 26, ?', 'Each term equals a perfect square plus 1: 1²+1=2, 2²+1=5, 3²+1=10, 4²+1=17, 5²+1=26.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00383', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 7, 'Find the next term in the series: 100, 50, 25, 12.5, ?', 'Each term is obtained by **dividing the previous term by 2**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00384', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 8, 'Find the next letter in the series: B, D, G, K, P, ?', 'The gap between letters increases by one each time: +2, +3, +4, +5, so the next gap is +6.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00385', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 9, 'Find the odd one out: 8, 27, 64, 100, 125', '8, 27, 64, and 125 are perfect cubes (2³, 3³, 4³, 5³).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00386', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 10, 'Find the odd one out: Triangle, Square, Pentagon, Circle', 'Triangle, Square, and Pentagon are all **polygons** made up of straight sides and vertices.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00387', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 11, 'Find the odd one out: Lion, Tiger, Leopard, Elephant', 'Lion, Tiger, and Leopard all belong to the **cat family (Felidae)**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00388', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 12, 'Find the odd one out: Delhi, Mumbai, Chennai, Maharashtra', 'Delhi, Mumbai, and Chennai are all **cities**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00389', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 13, 'Find the odd one out among the numbers: 2, 3, 5, 9, 11', '2, 3, 5, and 11 are all **prime numbers**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00390', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 14, 'Complete the analogy: Doctor is to Hospital as Teacher is to ?', 'A Doctor''s typical place of work is a Hospital.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00391', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 15, 'Complete the analogy: Pen is to Write as Knife is to ?', 'A Pen is the tool used to Write.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00392', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 16, 'Complete the analogy: Finger is to Hand as Leaf is to ?', 'A Finger is a part of the whole Hand.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00393', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 17, 'Complete the analogy: Author is to Book as Sculptor is to ?', 'An Author is the creator of a Book.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00394', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 18, 'Complete the analogy: Fish is to Water as Bird is to ?', 'A Fish''s natural habitat/medium of movement is Water.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00395', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 19, 'Complete the analogy: Puppy is to Dog as Kitten is to ?', 'A Puppy is the young one of a Dog.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00396', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 20, 'Complete the analogy: Hungry is to Food as Thirsty is to ?', 'Hunger is satisfied by Food.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00397', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 21, 'Complete the numeric analogy: 4 is to 16 as 6 is to ?', 'The relationship is **''square of the number''**: 4² = 16.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00398', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 22, 'Complete the numeric analogy: 5 is to 30 as 8 is to ?', 'The relationship is `n : n(n+1)`: 5 × 6 = 30.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00399', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 23, 'In a certain code, CAT is written as DBU. How would DOG be written in that code?', 'Each letter in the code is shifted **one place forward** in the alphabet: C→D, A→B, T→U.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00400', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 24, 'In a certain code, BOOK is written as ''2, 15, 15, 11'' (each letter''s position in the alphabet). How would PAGE be written?', 'Each letter is replaced by its **position number in the alphabet** (A=1, B=2, and so on).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00401', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 25, 'In a certain code, FRIEND is written as GSJFOE. How would CANDLE be written in the same code?', 'Each letter in the code is shifted **one place forward** in the alphabet: F→G, R→S, I→J, E→F, N→O, D→E.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00402', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 26, 'In a certain code, ROSE is written as URVH. How would LOTUS be written in the same code?', 'Each letter in the code is shifted **three places forward** in the alphabet: R→U, O→R, S→V, E→H.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00403', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 27, 'In a certain code, TABLE is written as GZYOV, where each letter is replaced by its ''opposite'' letter in the alphabet (A↔Z, B↔Y, C↔X, and so on). How would CHAIR be written in the same code?', 'Each letter is paired with the letter that is equally distant from the other end of the alphabet (position `p` maps to position `27-p`): T↔G, A↔Z, B↔Y, L↔O, E↔V, confirming the given code.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00404', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 28, 'Pointing to a photograph, a woman says, ''He is the son of my grandfather''s only son.'' How is the man in the photo related to the woman (assuming the woman is her father''s child)?', 'The woman''s grandfather''s only son is the woman''s own **father**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00405', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 29, 'Introducing a man, a woman said, ''His mother is the only daughter of my mother.'' How is the woman related to the man?', 'The only daughter of the woman''s mother is the **woman herself**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00406', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 30, 'A is the father of B, but B is not the son of A. What is B''s relationship to A?', 'Since B is not A''s son but A is B''s father, B must be female.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00407', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 31, 'P is Q''s brother. R is Q''s mother. S is R''s father. T is S''s mother. How is P related to T?', 'P and Q are siblings, children of R; R''s father is S, making S the maternal grandfather of P.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00408', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 32, 'Pointing to a man, a woman says, ''His wife is the only daughter of my father.'' How is the woman related to the man?', 'The only daughter of the woman''s father is the **woman herself**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00409', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 33, 'A man walks 5 km towards south, then turns left and walks 3 km, then turns left again and walks 5 km. How far and in which direction is he from his starting point?', 'Facing south and turning left means he now faces east; after turning left again from east, he faces north.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00410', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 34, 'Ravi walks 10 m towards North, turns right and walks 6 m, then turns right again and walks 10 m. How far and in which direction is he from his starting point?', 'Facing north and turning right means he now faces east; turning right again from east means he now faces south.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00411', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 35, 'One morning at sunrise, Suresh was facing the sun. He turned left, and then turned right. In which direction is he now facing?', 'At sunrise the sun rises in the **east**, so Suresh was initially facing east.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00412', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 36, 'Point A is 4 km north of point B. Point C is 3 km east of point A. What is the straight-line distance between points B and C?', 'Since AB (4 km, north-south) and AC (3 km, east-west) are perpendicular to each other, triangle ABC is right-angled at A.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00413', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 37, 'Statements: All cats are animals. All animals are living beings. Conclusion: All cats are living beings. Does the conclusion logically follow?', 'Since all cats belong to the group of animals, and all animals belong to the group of living beings, every cat must also be a living being.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00414', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 38, 'Statements: Some pens are books. All books are papers. Conclusion: Some pens are papers. Does the conclusion logically follow?', 'Since some pens overlap with the group of books, and all books fall entirely within the group of papers, those overlapping pens must also be papers.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00415', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 39, 'Statements: Some books are pens. Some pens are pencils. Conclusion: Some books are pencils. Does the conclusion logically follow?', 'Both premises are ''particular'' (some-type) statements, and in syllogistic logic, two particular premises cannot yield a valid conclusion, since the overlapping ''pens'' in each statement need not be the same pens.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00416', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 40, 'Five friends A, B, C, D, and E sit in a row facing North. D is at the left end, A is immediately right of D, B is immediately right of A, C is immediately right of B, and E is at the right end. Who sits in the middle (third position)?', 'The seating order from left to right is **D, A, B, C, E**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00417', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 41, 'Four friends P, Q, R, S sit around a circular table facing the centre. Q is to the immediate right of P, R is to the immediate right of Q, and S is to the immediate right of R. Who is to the immediate right of S?', 'Moving around the table in order: P, Q, R, S, and then back to P.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00418', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 42, 'In a class of 40 students, Rohan ranks 12th from the top. What is his rank from the bottom?', 'Rank from the bottom is calculated as: total students − rank from top + 1 = 40 − 12 + 1.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00419', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 43, 'Sita is 15th from the left end and 22nd from the right end in a row of students. How many students are there in the row in total?', 'Total students = (position from left − 1) + (position from right − 1) + 1 = 14 + 21 + 1.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00420', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 44, 'If today is Monday, what day of the week will it be after 61 days?', 'Since a week has 7 days, dividing 61 by 7 leaves a remainder of **5** (61 = 7×8 + 5).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00421', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 45, 'Which day of the week was 15 August 1947 (the day India became independent)?', 'Using calendar calculation, **15 August 1947** fell on a **Friday**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00422', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 46, 'At what time between 3 and 4 o''clock will the hour and minute hands of a clock be exactly opposite each other (180° apart)?', 'At 3 o''clock the hour hand is at 90°; the minute hand gains on it at a relative speed of 5.5° per minute, and needs to be 180° ahead of the hour hand''s starting position.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00423', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 47, 'How many times do the hour and minute hands of a clock coincide (overlap exactly) in a 24-hour day?', 'The hands coincide 11 times every 12 hours, not 12 times, because the overlap near 12 o''clock is shared between the end of one 12-hour cycle and the start of the next.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00424', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 48, 'What is the mirror image of the clock time 4:20, as reflected in a vertical mirror?', 'The mirror image of a clock time is found using the formula `11:60 − given time`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00425', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 49, 'What is the mirror image of the clock time 8:15, as reflected in a vertical mirror?', 'The mirror image of a clock time is found using the formula `11:60 − given time`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00426', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 50, 'If ''×'' means ''÷'', ''÷'' means ''+'', ''+'' means ''×'', and ''−'' stays as ''−'', evaluate: 16 × 4 ÷ 2 + 8 − 3 (using the new meanings)', 'Replacing each symbol with its new meaning turns the expression into: `16 ÷ 4 + 2 × 8 − 3`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00427', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 51, 'If ''+'' means ''×'', ''×'' means ''−'', ''−'' means ''÷'', and ''÷'' means ''+'', evaluate: 10 + 2 × 6 − 3 ÷ 1 (using the new meanings)', 'Replacing each symbol with its new meaning turns the expression into: `10 × 2 − 6 ÷ 3 + 1`.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00428', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 52, 'Among the words ''Father, Mother, Son, Family'', which single word best represents a category that includes all the others as its members?', 'A ''Father'', ''Mother'', and ''Son'' are all individual members that together make up a **Family**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00429', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 53, 'How would the relationship between the groups ''Teacher'', ''Men'', and ''Indians'' best be represented in a Venn diagram?', 'Some teachers are men, some men are Indians, and some teachers are Indians, but none of the three groups is wholly contained within another, nor are they entirely separate.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00430', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 54, 'Notice outside a library reads: ''Please maintain silence in the library.'' Assumption: People need to be reminded that silence should be maintained in the library. Is this assumption implicit in the statement?', 'Notices of this kind are put up precisely because visitors might not otherwise realise or remember that silence is expected.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00431', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 55, 'All students who scored above 90% received a scholarship. Rani did not receive a scholarship. What can be validly concluded about Rani''s score?', 'The statement guarantees a scholarship only for those scoring above 90%; since Rani did not receive one, she cannot belong to that group.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00432', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 56, 'If the letters of the word ''DELHI'' are rearranged in alphabetical order, which letters remain in their original position?', 'The original order is D-E-L-H-I (positions 1-5); arranged alphabetically it becomes D-E-H-I-L.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00433', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 57, 'Which letter is 5th to the right of the 13th letter from the left in the English alphabet?', 'The 13th letter from the left is **M**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00434', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 58, 'Find the next number in the series: 6, 11, 21, 36, 56, ?', 'The differences between consecutive terms increase by 5 each time: +5, +10, +15, +20, so the next difference is +25.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00435', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 59, 'Find the missing number in the series: 1, 1, 2, 3, 5, 8, 13, ?', 'This is the **Fibonacci-style series**, where each term is the sum of the two preceding terms: 5+8=13.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00436', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 60, 'Complete the analogy: Soldier is to Army as Sailor is to ?', 'A Soldier is a member of the Army.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00437', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 61, 'Complete the analogy: Thermometer is to Temperature as Barometer is to ?', 'A Thermometer is an instrument used to measure Temperature.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00438', 'defence-exam-bank', 'Reasoning (Verbal & Non-Verbal)', 6, 62, 'Find the odd one out: Clock, Watch, Calendar, Stopwatch', 'Clock, Watch, and Stopwatch are all instruments used to measure **time of day or duration**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00439', 'defence-exam-bank', 'English Language', 7, 0, 'What is a ''noun'', and what are its main types?', 'A **noun** is a word that names a person, place, thing, or idea.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00440', 'defence-exam-bank', 'English Language', 7, 1, 'What is the difference between a ''transitive'' and an ''intransitive'' verb?', 'A **transitive verb** requires a direct object to complete its meaning (e.g., ''She reads a book'').
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00441', 'defence-exam-bank', 'English Language', 7, 2, 'Convert the following sentence into passive voice: ''The teacher teaches the students.''', 'In passive voice, the object becomes the subject and the verb changes to a form of ''be'' plus the past participle.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00442', 'defence-exam-bank', 'English Language', 7, 3, 'Convert the following sentence into active voice: ''The cake was eaten by the children.''', 'In active voice, the original subject (doer) becomes the grammatical subject, and the verb is restored to its active form.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00443', 'defence-exam-bank', 'English Language', 7, 4, 'Convert the following sentence into indirect (reported) speech: He said, ''I am going to the market.''', 'In indirect speech, the tense generally shifts backward, and pronouns are adjusted to match the reporting context.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00444', 'defence-exam-bank', 'English Language', 7, 5, 'Convert the following sentence into indirect (reported) speech: She said, ''I will complete the work tomorrow.''', '''Will'' changes to ''would'', and ''tomorrow'' changes to ''the next day'' in indirect speech.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00445', 'defence-exam-bank', 'English Language', 7, 6, 'Fill in the blank with the correct article: ''___ European country has its own unique culture.'' (Choose: A/An)', 'Although ''European'' begins with a vowel letter, it is pronounced with a **consonant sound (''yoo-ropean'')**, so the article ''a'' is used, not ''an''.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00446', 'defence-exam-bank', 'English Language', 7, 7, 'Fill in the blank with the correct article: ''He is ___ honest man.'' (Choose: a/an)', 'The word ''honest'' begins with a **silent ''h''**, so it starts with a vowel sound, requiring the article ''an''.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00447', 'defence-exam-bank', 'English Language', 7, 8, 'Choose the correctly spelt word: ''Accommodate'' or ''Acommodate''?', 'The correct spelling has **double ''c'' and double ''m''**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00448', 'defence-exam-bank', 'English Language', 7, 9, 'Choose the correctly spelt word: ''Occurence'' or ''Occurrence''?', 'The correct spelling has **double ''c'' and double ''r''**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00449', 'defence-exam-bank', 'English Language', 7, 10, 'What is the synonym of the word ''Benevolent''?', '''Benevolent'' means kind and generous in nature.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00450', 'defence-exam-bank', 'English Language', 7, 11, 'What is the synonym of the word ''Candid''?', '''Candid'' means truthful and straightforward.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00451', 'defence-exam-bank', 'English Language', 7, 12, 'What is the antonym of the word ''Abundant''?', '''Abundant'' means existing in large quantities.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00452', 'defence-exam-bank', 'English Language', 7, 13, 'What is the antonym of the word ''Diligent''?', '''Diligent'' means showing care and effort in one''s work.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00453', 'defence-exam-bank', 'English Language', 7, 14, 'What is the antonym of the word ''Optimistic''?', '''Optimistic'' means hopeful and confident about the future.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00454', 'defence-exam-bank', 'English Language', 7, 15, 'What does the idiom ''to beat around the bush'' mean?', 'This idiom means to **avoid talking about the main point directly**, often to delay an uncomfortable topic.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00455', 'defence-exam-bank', 'English Language', 7, 16, 'What does the idiom ''to spill the beans'' mean?', 'This idiom means to **reveal a secret**, often accidentally or prematurely.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00456', 'defence-exam-bank', 'English Language', 7, 17, 'What does the idiom ''once in a blue moon'' mean?', 'This idiom means **something that happens very rarely**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00457', 'defence-exam-bank', 'English Language', 7, 18, 'What does the idiom ''to hit the nail on the head'' mean?', 'This idiom means to **describe exactly what is causing a situation or problem; to be precisely correct**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00458', 'defence-exam-bank', 'English Language', 7, 19, 'What does the idiom ''to burn the midnight oil'' mean?', 'This idiom means to **work or study late into the night**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00459', 'defence-exam-bank', 'English Language', 7, 20, 'Provide the one-word substitution for: ''A person who can speak many languages''', 'The correct term is **''Polyglot''**, referring to someone proficient in multiple languages.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00460', 'defence-exam-bank', 'English Language', 7, 21, 'Provide the one-word substitution for: ''A person who loves mankind''', 'The correct term is **''Philanthropist''**, referring to someone who promotes human welfare, often through charitable giving.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00461', 'defence-exam-bank', 'English Language', 7, 22, 'Provide the one-word substitution for: ''A place where weapons and ammunition are stored''', 'The correct term is **''Arsenal''** (also ''armoury''), referring to a storage facility for weapons and military equipment.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00462', 'defence-exam-bank', 'English Language', 7, 23, 'Provide the one-word substitution for: ''One who is not easily discouraged or defeated''', 'The correct term is **''Indomitable''**, describing someone with unyielding determination.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00463', 'defence-exam-bank', 'English Language', 7, 24, 'Provide the one-word substitution for: ''A statement that is obviously true and needs no proof''', 'The correct term is **''Axiom'' (or ''truism'')**, referring to a self-evident truth.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00464', 'defence-exam-bank', 'English Language', 7, 25, 'Identify the error, if any, in the sentence: ''Each of the students have submitted their assignment.''', 'The subject ''Each'' is singular and must take a **singular verb**, not ''have''.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00465', 'defence-exam-bank', 'English Language', 7, 26, 'Identify the error, if any, in the sentence: ''Neither of the two options are correct.''', '''Neither'' is singular and requires a **singular verb**, not ''are''.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00466', 'defence-exam-bank', 'English Language', 7, 27, 'Identify the error, if any, in the sentence: ''She don''t like coffee.''', 'The subject ''She'' (third person singular) requires **''doesn''t''**, not ''don''t''.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00467', 'defence-exam-bank', 'English Language', 7, 28, 'Identify the error, if any, in the sentence: ''He is married with a doctor.''', 'The correct preposition to use after ''married'' when referring to a spouse is **''to''**, not ''with''.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00468', 'defence-exam-bank', 'English Language', 7, 29, 'Identify the error, if any, in the sentence: ''I am agree with your opinion.''', '''Agree'' is a verb itself and should not be preceded by ''am''; the auxiliary verb is unnecessary here.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00469', 'defence-exam-bank', 'English Language', 7, 30, 'Fill in the blank with the correct preposition: ''He is good ___ mathematics.''', 'The adjective ''good'' in the sense of being skilled at something is followed by the preposition **''at''**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00470', 'defence-exam-bank', 'English Language', 7, 31, 'Fill in the blank with the correct preposition: ''She is afraid ___ spiders.''', 'The adjective ''afraid'' is followed by the preposition **''of''**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00471', 'defence-exam-bank', 'English Language', 7, 32, 'Fill in the blank with the correct preposition: ''The train arrived ___ the station on time.''', 'When referring to arrival at a specific point/building, the correct preposition is **''at''**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00472', 'defence-exam-bank', 'English Language', 7, 33, 'What is the plural form of the noun ''Criterion''?', '''Criterion'' is a word of Greek origin, and its correct plural form is **''Criteria''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00473', 'defence-exam-bank', 'English Language', 7, 34, 'What is the past tense and past participle of the irregular verb ''Begin''?', 'The past tense of ''begin'' is **''began''**, and the past participle is **''begun''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00474', 'defence-exam-bank', 'English Language', 7, 35, 'What is the past tense and past participle of the irregular verb ''Swim''?', 'The past tense of ''swim'' is **''swam''**, and the past participle is **''swum''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00475', 'defence-exam-bank', 'English Language', 7, 36, 'What is the comparative and superlative form of the adjective ''Good''?', '''Good'' is an irregular adjective: its comparative form is **''better''**, and its superlative form is **''best''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00476', 'defence-exam-bank', 'English Language', 7, 37, 'What is the comparative and superlative form of the adjective ''Bad''?', '''Bad'' is an irregular adjective: its comparative form is **''worse''**, and its superlative form is **''worst''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00477', 'defence-exam-bank', 'English Language', 7, 38, 'Choose the correct word: ''Their/There/They''re going to the exhibition tomorrow.''', 'The sentence requires the **contraction of ''they are''**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00478', 'defence-exam-bank', 'English Language', 7, 39, 'What is the difference in usage between ''Its'' and ''It''s''?', '**''Its''** is a possessive pronoun (e.g., ''The dog wagged its tail''), while **''It''s''** is the contraction of ''it is'' or ''it has'' (e.g., ''It''s raining'').', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00479', 'defence-exam-bank', 'English Language', 7, 40, 'What is the correct form: ''Less'' or ''Fewer'', for the sentence: ''There are ___ apples in the basket today.''', '''Fewer'' is used with **countable nouns** (like apples), while ''less'' is used with uncountable nouns.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00480', 'defence-exam-bank', 'English Language', 7, 41, 'Which word correctly completes the sentence: ''The committee ___ divided on the issue.'' (is/are)', 'When a collective noun like ''committee'' is considered as a single unit, it takes a **singular verb**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00481', 'defence-exam-bank', 'English Language', 7, 42, 'What type of conjunction is used in the sentence: ''She was tired, yet she continued working''?', '''Yet'' here is a **coordinating conjunction**, showing a contrast between the two independent clauses.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00482', 'defence-exam-bank', 'English Language', 7, 43, 'Identify the figure of speech in the sentence: ''The stars danced in the night sky.''', 'Giving human qualities (dancing) to a non-human object (stars) is an example of **personification**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00483', 'defence-exam-bank', 'English Language', 7, 44, 'Identify the figure of speech in the sentence: ''Her smile was as bright as the sun.''', 'This sentence compares two things using ''as...as'', which is an example of a **simile**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00484', 'defence-exam-bank', 'English Language', 7, 45, 'Identify the figure of speech in the sentence: ''Time is money.''', 'This sentence makes a direct, implicit comparison without using ''like'' or ''as'', which is an example of a **metaphor**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00485', 'defence-exam-bank', 'English Language', 7, 46, 'What is the synonym of the word ''Meticulous''?', '''Meticulous'' means showing great attention to detail.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00486', 'defence-exam-bank', 'English Language', 7, 47, 'What is the antonym of the word ''Generous''?', '''Generous'' means willing to give freely.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00487', 'defence-exam-bank', 'English Language', 7, 48, 'Provide the one-word substitution for: ''A person who does not believe in the existence of God''', 'The correct term is **''Atheist''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00488', 'defence-exam-bank', 'English Language', 7, 49, 'Provide the one-word substitution for: ''Government by the few, especially a privileged class''', 'The correct term is **''Oligarchy''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00489', 'defence-exam-bank', 'English Language', 7, 50, 'What does the idiom ''to let the cat out of the bag'' mean?', 'This idiom means to **reveal a secret unintentionally**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00490', 'defence-exam-bank', 'English Language', 7, 51, 'What does the idiom ''a blessing in disguise'' mean?', 'This idiom refers to **something that seems bad or unlucky at first but eventually turns out to be beneficial**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00491', 'defence-exam-bank', 'English Language', 7, 52, 'Identify the error, if any, in the sentence: ''He has gone to market yesterday.''', 'Using ''yesterday'' (a specific past time marker) requires the **simple past tense**, not the present perfect (''has gone'').
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00492', 'defence-exam-bank', 'English Language', 7, 53, 'Identify the error, if any, in the sentence: ''Between you and I, this is a secret.''', 'The preposition ''between'' must be followed by **object pronouns**, so ''I'' should be ''me''.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00493', 'defence-exam-bank', 'English Language', 7, 54, 'Identify the error, if any, in the sentence: ''One of my friend is coming to the party.''', 'The phrase ''one of'' must be followed by a **plural noun**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00494', 'defence-exam-bank', 'English Language', 7, 55, 'Fill in the blank with the correct preposition: ''He was accused ___ theft.''', 'The verb ''accused'' takes the preposition **''of''**.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00495', 'defence-exam-bank', 'English Language', 7, 56, 'What is the correct past tense form of the irregular verb ''Go''?', 'The past tense of ''go'' is **''went''**, and the past participle is **''gone''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00496', 'defence-exam-bank', 'English Language', 7, 57, 'What is the correct past tense form of the irregular verb ''Think''?', 'The past tense of ''think'' is **''thought''**, and the past participle is also **''thought''**.', '2026-11-14T06:17:56.365Z');
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00497', 'defence-exam-bank', 'English Language', 7, 58, 'Convert the following sentence into indirect speech: He said to me, ''Where do you live?''', 'In reported questions, the sentence structure changes to a statement form (no inversion), and the tense shifts backward.
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00498', 'defence-exam-bank', 'English Language', 7, 59, 'What is the difference between ''Affect'' and ''Effect'' as commonly used in English?', '**''Affect''** is generally used as a **verb** meaning to influence something (e.g., ''The weather affected the match'').
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00499', 'defence-exam-bank', 'English Language', 7, 60, 'What is the correct usage: ''I have been living here since/for 2015''?', '''Since'' is used with a specific **point in time** (such as a year or date).
INSERT INTO questions (id, set_id, topic_label, topic_order, sort_order, q, a, created_at) VALUES ('defence-q00500', 'defence-exam-bank', 'English Language', 7, 61, 'What is the correct usage: ''I have been working here for/since five years''?', '''For'' is used with a **duration or period of time**.
